INSERT INTO "PUBLIC"."REVISION" VALUES
(510, 'Card', 124, 1, TIMESTAMP WITH TIME ZONE '2025-09-12 10:07:18.48786+03', '{"description":"Completeness rates per location per year, based on country provided population and crude birth rate statistics","archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"Completeness rates","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n\tCOALESCE(br.register_count, 0) AS register_count,\n\t((register_count / (s.total_population / 1000 * s.crude_birth_rate)) * 100) AS completeness_rate\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"register_count","table.cell_column":"year"},"parameters":[],"dashboard_id":12}', FALSE, TRUE, NULL, FALSE, 'v0.56.4 (aeaacd0)'),
