INSERT INTO SYSTEM_LOB_STREAM VALUES(44, 1, '3333333333333,"q1":0.20833333333333331,"q3":7.395833333333334,"max":11.833333333333334,"sd":5.509816051073454,"avg":3.8020833333333335}}},"base_type":"type/Decimal"}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":9,"query_type":"native","name":"Births completeness rates","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_hierarchy AS (\n    SELECT id, parent_id, id AS root_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT l.id, l.parent_id, h.root_id\n    FROM analytics.locations l\n    JOIN location_hierarchy h ON l.parent_id = h.id\n),\ncounts AS (\n    SELECT l.id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.locations l\n    JOIN analytics.event_actions ea \n      ON ea.action_type = ''REGISTER''\n     AND ea.event_type = ''birth''\n     AND ea.created_at IS NOT NULL\n     AND ea.created_at_location = l.id\n    GROUP BY l.id, year\n),\nbirth_registrations_per_location AS (\n    SELECT root.id   AS location_id,\n           root.name AS location_name,\n           c.year,\n           COALESCE(SUM(c.cnt), 0) AS register_count\n    FROM location_hierarchy h\n    JOIN analytics.locations root ON root.id = h.root_id\n    LEFT JOIN counts c ON h.id = c.id\n    GROUP BY root.id, root.name, c.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n\tCOALESCE(br.register_count, 0) AS register_count,\n\t((register_count / (s.total_population / 1000 * s.crude_birth_rate)) * 100) AS completeness_rate\nFROM analytics.locations l\nJOIN analytics.location_statistics s \n       ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br \n       ON br.location_id = l.id AND br.year = s.year\nORDER BY s.year DESC, register_count DESC;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["name"],"graph.metrics":["completeness_rate"]},"parameters":[],"dashboard_id":null}', NULL); 
INSERT INTO SYSTEM_LOB_STREAM VALUES(45, 0, '{"description":"Completeness rates per location per year, based on country provided population and crude birth rate statistics","archived":false,"collection_position":1,"source_card_id":null,"table_id":null,"result_metadata":[{"name":"id","database_type":"uuid","base_type":"type/UUID","display_name":"id","semantic_type":"type/PK","field_ref":["field","id",{"base-type":"type/UUID"}]},{"name":"name","database_type":"text","base_type":"type/Text","display_name":"name","semantic_type":"type/Name","field_ref":["field","name",{"base-type":"type/Text"}]},{"name":"year","database_type":"int4","base_type":"type/Integer","display_name":"year","field_ref":["field","year",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"crude_birth_rate","database_type":"int4","base_type":"type/Integer","display_name":"crude_birth_rate","field_ref":["field","crude_birth_rate",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"total_population","database_type":"int4","base_type":"type/Integer","display_name":"total_population","field_ref":["field","total_population",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"estimated_births","database_type":"int4","base_type":"type/Integer","display_name":"estimated_births","field_ref":["field","estimated_births",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"register_count","database_type":"numeric","base_type":"type/Decimal","display_name":"register_count","field_ref":["field","register_count",{"base-type":"type/Decimal"}],"semantic_type":null},{"name":"level","database_type":"int4","base_type":"type/Integer","display_name":"level","field_ref":["field","level",{"base-type":"type/Integer"}],"semantic_type":null}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":9,"query_type":"native","name":"Births completeness rates","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE levels AS (\n    -- root = 1, children increment\n    SELECT id, parent_id, 1 AS level\n    FROM analytics.locations\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT l.id, l.parent_id, lv.level + 1\n    FROM analytics.locations l\n    JOIN levels lv ON l.parent_id = lv.id\n),\n-- ancestor/descendant closure: every node is ancestor of itself and all its descendants\nclosure AS (\n    SELECT id AS ancestor_id, id AS descendant_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT c.ancestor_id, l.id AS descendant_id\n    FROM closure c\n    JOIN analytics.locations l ON l.parent_id = c.descendant_id\n),\n-- counts at leaf/origin locations by year\ncounts AS (\n    SELECT ea.created_at_location AS location_id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.event_actions ea\n    WHERE ea.action_type = ''REGISTER''\n      AND ea.event_type  = ''birth''\n      AND ea.created_at IS NOT NULL\n      AND ea.created_at_location IS NOT NULL\n    GROUP BY ea.created_at_location, year\n),\n-- roll up descendant counts to each ancestor (this is the named query)\nbirth_registrations_per_location AS (\n    SELECT c.ancestor_id AS location_id,\n           cnt.year,\n           SUM(cnt.cnt) AS register_count\n    FROM closure c\n    JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY c.ancestor_id, cnt.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count,\n    lv.level\nFROM analytics.locations l\nJOIN analytics.location_statistics s\n  ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br\n  ON br.location_id = l.id AND br.year = s.year\nLEFT JOIN levels lv\n  ON lv.id = l.id\nORDER BY s.year DESC, register_count DESC;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["name"],"table.pivot_column"', NULL);     
