(600, 'Dashboard', 12, 1, TIMESTAMP WITH TIME ZONE '2025-09-16 12:28:13.081952+03', U&'{"description":null,"archived":false,"collection_position":null,"tabs":[{"id":23,"dashboard_id":12,"name":"Births","position":0},{"id":24,"dashboard_id":12,"name":"Deaths","position":1}],"enable_embedding":false,"collection_id":8,"name":"Completness Rates Dashboard","width":"fixed","embedding_params":null,"cache_ttl":null,"cards":[{"size_x":24,"dashboard_tab_id":23,"series":[],"inline_parameters":[],"action_id":null,"col":0,"id":109,"parameter_mappings":[],"card_id":null,"visualization_settings":{"virtual_card":{"name":null,"display":"text","visualization_settings":{},"archived":false},"text":"The no. of registrations, expressed as a % of the total estimated no. of births occurring. \\n\\nCompleteness Rate (%) = (Number of Registered Births** / Estimated Total Number of Births) \00d7 100\\n\\n** only registrations where child was under 1 years old at time of registration \\n\\n\\nTo do:\\n- Overall Completeness rate for Farajaland \\n- Overtime by Farajaland \\n- Completeness compare all states\\n- Completness compare all district "},"size_y":7,"dashboard_id":12,"row":0},{"size_x":24,"dashboard_tab_id":23,"series":[],"inline_parameters":[],"action_id":null,"col":0,"id":110,"parameter_mappings":[{"parameter_id":"3e9b2029","card_id":126,"target":["dimension",["field","year",{"base-type":"type/Integer"}],{"stage-number":0}]}],"card_id":126,"visualization_settings":{"click_behavior":{"parameterMapping":{"[\\"dimension\\",[\\"field\\",276,{\\"base-type\\":\\"type/Text\\",\\"join-alias\\":\\"Admin Locations - name\\"}],{\\"stage-number\\":0}]":{"source":{"type":"column","id":"name","name":"name"},"target":{"type":"dimension","id":"[\\"dimension\\",[\\"field\\",276,{\\"base-type\\":\\"type/Text\\",\\"join-alias\\":\\"Admin Locations - name\\"}],{\\"stage-number\\":0}]","dimension":["dimension",["field",276,{"base-type":"type/Text","join-alias":"Admin Locations - name"}],{"stage-number":0