(610, 'Dashboard', 12, 1, TIMESTAMP WITH TIME ZONE '2025-10-10 13:32:18.054903+03', U&'{"description":null,"archived":false,"collection_position":null,"tabs":[{"id":23,"dashboard_id":12,"name":"Births","position":0},{"id":24,"dashboard_id":12,"name":"Deaths","position":1}],"enable_embedding":false,"collection_id":8,"name":"Completeness Rates Dashboard","width":"fixed","embedding_params":null,"cache_ttl":null,"cards":[{"size_x":24,"dashboard_tab_id":23,"series":[],"inline_parameters":[],"action_id":null,"col":0,"id":109,"parameter_mappings":[],"card_id":null,"visualization_settings":{"virtual_card":{"name":null,"display":"text","visualization_settings":{},"archived":false},"text":"The no. of registrations, expressed as a % of the total estimated no. of births occurring. \\n\\nCompleteness Rate (%) = (Number of Registered Births** / Estimated Total Number of Births) \00d7 100\\n\\n** only registrations where child was under 1 years old at time of registration \\n\\n\\nTo do:\\n- Overall Completeness rate for Farajaland \\n- Overtime by Farajaland \\n- Completeness compare all states\\n- Completness compare all district "},"size_y":7,"dashboard_id":12,"row":0},{"size_x":24,"dashboard_tab_id":23,"series":[],"inline_parameters":[],"action_id":null,"col":0,"id":110,"parameter_mappings":[{"parameter_id":"3e9b2029","card_id":126,"target":["dimension",["field","year",{"base-type":"type/Integer"}],{"stage-number":0}]}],"card_id":126,"visualization_settings":{"click_behavior":{"parameterMapping":{"[\\"dimension\\",[\\"field\\",276,{\\"base-type\\":\\"type/Text\\",\\"join-alias\\":\\"Admin Locations - name\\"}],{\\"stage-number\\":0}]":{"source":{"type":"column","id":"name","name":"name"},"target":{"type":"dimension","id":"[\\"dimension\\",[\\"field\\",276,{\\"base-type\\":\\"type/Text\\",\\"join-alias\\":\\"Admin Locations - name\\"}],{\\"stage-number\\":0}]","dimension":["dimension",["field",276,{"base-type":"type/Text","join-alias":"Admin Locations - name"}],{"stage-number":0}]},"id":"[\\"dimension\\",[\\"field\\",276,{\\"base-type\\":\\"type/Text\\",\\"join-alias\\":\\"Admin Locations - name\\"}],{\\"stage-number\\":0}]"}},"targetId":128,"linkType":"question","type":"link"}},"size_y":9,"dashboard_id":12,"row":7},{"size_x":24,"dashboard_tab_id":23,"series":[],"inline_parameters":[],"action_id":null,"col":0,"id":111,"parameter_mappings":[{"parameter_id":"3e9b2029","card_id":127,"target":["dimension",["field","year",{"base-type":"type/Integer"}],{"stage-number":0}]}],"card_id":127,"visualization_settings":{"click_behavior":{"type":"link","linkType":"question","targetId":128,"parameterMapping":{}}},"size_y":10,"dashboard_id":12,"row":16},{"size_x":24,"dashboard_tab_id":23,"series":[],"inline_parameters":[],"action_id":null,"col":0,"id":112,"parameter_mappings":[],"card_id":128,"visualization_settings":{"click_behavior":{"parameterMapping":{"[\\"dimension\\",[\\"field\\",\\"name\\",{\\"base-type\\":\\"type/Text\\"}],{\\"stage-number\\":0}]":{"source":{"type":"column","id":"name_2","name":"Admin Locations - name \2192 Name"},"target":{"type":"dimension","id":"[\\"dimension\\",[\\"field\\",\\"name\\",{\\"base-type\\":\\"type/Text\\"}],{\\"stage-number\\":0}]","dimension":["dimension",["field","name",{"base-type":"type/Text"}],{"stage-number":0}]},"id":"[\\"dimension\\",[\\"field\\",\\"name\\",{\\"base-type\\":\\"type/Text\\"}],{\\"stage-number\\":0}]"}},"targetId":128,"linkType":"question","type":"link"}},"size_y":8,"dashboard_id":12,"row":26}],"archived_directly":false,"parameters":[{"slug":"year","default":["2025"],"name":"Year","isMultiSelect":false,"type":"number/=","sectionId":"number","values_source_type":"static-list","id":"3e9b2029","values_source_config":{"values":[["2025"],["2024"],["2023"],["2022"],["2021"],["2020"],["2019"],["2018"],["2017"],["2016"],["2015"],["2014"],["2013"],["2012"],["2011"],["2010"],["2009"]]}}],"auto_apply_filters":true}', FALSE, FALSE, NULL, FALSE, 'v0.56.4 (aeaacd0)');
INSERT INTO SYSTEM_LOB_STREAM VALUES(59, 0, '{"description":"Completeness rates per location per year, based on country provided population and crude birth rate statistics","archived":false,"collection_position":1,"source_card_id":null,"table_id":null,"result_metadata":[{"name":"id","database_type":"uuid","base_type":"type/UUID","display_name":"id","semantic_type":"type/PK","field_ref":["field","id",{"base-type":"type/UUID"}]},{"name":"name","database_type":"text","base_type":"type/Text","display_name":"name","semantic_type":"type/Name","field_ref":["field","name",{"base-type":"type/Text"}]},{"name":"year","database_type":"int4","base_type":"type/Integer","display_name":"year","field_ref":["field","year",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"crude_birth_rate","database_type":"numeric","base_type":"type/Decimal","display_name":"crude_birth_rate","semantic_type":"type/Share","field_ref":["field","crude_birth_rate",{"base-type":"type/Decimal"}]},{"name":"total_population","database_type":"int4","base_type":"type/Integer","display_name":"total_population","field_ref":["field","total_population",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"estimated_births","database_type":"numeric","base_type":"type/Decimal","display_name":"estimated_births","field_ref":["field","estimated_births",{"base-type":"type/Decimal"}],"semantic_type":null},{"name":"register_count","database_type":"numeric","base_type":"type/Decimal","display_name":"register_count","field_ref":["field","register_count",{"base-type":"type/Decimal"}],"semantic_type":null},{"name":"completeness_rate","database_type":"numeric","base_type":"type/Decimal","display_name":"completeness_rate","semantic_type":"type/Share","field_ref":["field","completeness_rate",{"base-type":"type/Decimal"}]},{"name":"level","database_type":"int4","base_type":"type/Integer","display_name":"level","field_ref":["field","level",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"level_name","database_type":"text","base_type":"type/Text","display_name":"level_name","field_ref":["field","level_name",{"base-type":"type/Text"}],"semantic_type":null}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":9,"query_type":"native","name":"Births completeness rates","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE levels AS (\n    -- root = 1, children increment\n    SELECT id, parent_id, 1 AS level\n    FROM analytics.locations\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT l.id, l.parent_id, lv.level + 1\n    FROM analytics.locations l\n    JOIN levels lv ON l.parent_id = lv.id\n),\n-- ancestor/descendant closure: every node is ancestor of itself and all its descendants\nclosure AS (\n    SELECT id AS ancestor_id, id AS descendant_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT c.ancestor_id, l.id AS descendant_id\n    FROM closure c\n    JOIN analytics.locations l ON l.parent_id = c.descendant_id\n),\n-- counts at leaf/origin locations by year\ncounts AS (\n\tSELECT ea.created_at_location AS location_id,\n\t       EXTRACT(YEAR FROM ea.created_at)::int AS year,\n\t       COUNT(*) AS cnt\n\tFROM analytics.event_actions ea\n\tWHERE ea.action_type = ''REGISTER''\n\t  AND ea.event_type  = ''birth''\n\t  AND ea.created_at IS NOT NULL\n\t  AND ea.created_at_location IS NOT NULL\n\t  AND (ea.declaration->>''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\n\tGROUP BY ea.created_at_location, year\n),\n-- roll up descendant counts to each ancestor (this is the named query)\nbirth_registrations_per_location AS (\n    SELECT c.ancestor_id AS location_id,\n           cnt.year,\n           SUM(cnt.cnt) AS register_count\n    FROM closure c\n    JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY c.ancestor_id, cnt.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count,\n\', NULL); 
INSERT INTO SYSTEM_LOB_STREAM VALUES(59, 1, 't(register_count / (s.total_population / 1000 * s.crude_birth_rate) * 100) as completeness_rate,\n    lv.level,\n    ll.name AS level_name\nFROM analytics.locations l\nJOIN analytics.location_statistics s\n  ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br\n  ON br.location_id = l.id AND br.year = s.year\nLEFT JOIN levels lv\n  ON lv.id = l.id\nLEFT JOIN analytics.location_levels ll\n  ON ll.level = lv.level\nORDER BY s.year DESC, register_count DESC;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["name"],"table.pivot_column":"crude_birth_rate","table.cell_column":"year","graph.metrics":[]},"parameters":[],"dashboard_id":null}', NULL);               
