(736, 'Card', 161, 1, TIMESTAMP WITH TIME ZONE '2025-12-10 14:28:30.991433+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"IDENT","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT\n  ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n  to_char((ea.declaration->>''deceased_dob'')::date, ''DD/MM/YYYY'') AS \"DateBirth\",\n  to_char((ea.declaration->>''deceased_eventDate'')::date, ''DD/MM/YYYY'') AS \"DateDeath\",\n  ea.declaration->>''deceased_gender'' AS \"SEX\",\n  (ea.declaration->>''deceased_deceasedAge'')::int AS \"AGE\",\n  0 AS \"MannerOfDeath\"\n\nFROM analytics.event_actions ea\n\nWHERE ea.registration_number IN (\n    SELECT registration_number\n    FROM analytics.event_actions\n    GROUP BY registration_number\n    HAVING COUNT(*) = 1\n);\n"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"Deceased DOB","table.cell_column":"Deceased age"},"parameters":[],"dashboard_id":14}', FALSE, FALSE, NULL, FALSE, 'v0.56.4 (aeaacd0)'),
(737, 'Card', 161, 1, TIMESTAMP WITH TIME ZONE '2025-12-10 14:31:21.972852+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"IDENT","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT\n  ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n  to_char((ea.declaration->>''deceased_dob'')::date, ''DD/MM/YYYY'') AS \"DateBirth\",\n  to_char((ea.declaration->>''deceased_eventDate'')::date, ''DD/MM/YYYY'') AS \"DateDeath\",\n  ea.declaration->>''deceased_gender'' AS \"SEX\",\n  (ea.declaration->>''deceased_deceasedAge'')::int AS \"AGE\",\n  0 AS \"MannerOfDeath\"\n\nFROM analytics.event_actions ea\n\nWHERE \n  -- Only unique registration_numbers\n  ea.registration_number IN (\n      SELECT registration_number\n      FROM analytics.event_actions\n      GROUP BY registration_number\n      HAVING COUNT(*) = 1\n  )\n  AND\n  -- Only rows where irisOutput_ucCode === ''Default''\n  (ea.declaration->>''irisOutput_ucCode'') = ''Default'';\n"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"Deceased DOB","table.cell_column":"Deceased age"},"parameters":[],"dashboard_id":14}', FALSE, FALSE, NULL, FALSE, 'v0.56.4 (aeaacd0)'),
