INSERT INTO SYSTEM_LOB_STREAM VALUES(91, 0, '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":14,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"MEDCOD","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH base AS (\n  SELECT DISTINCT ON (ea.event_id) *\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND ea.declaration->>''irisOutput_ucCode'' IS NULL\n  ORDER BY ea.event_id, ea.created_at DESC\n)\n\nSELECT *\nFROM (\n  -- Line 0\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    0 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_immediateCauseOfDeath'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherImmediateCauseOfDeath''\n      ELSE base.declaration->>''eventDetails_immediateCauseOfDeath''\n    END AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      base.declaration->>''eventDetails_immediateCauseOfDeathInterval'',\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 1\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    1 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause1'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause1''\n      ELSE base.declaration->>''eventDetails_antecedentCause1''\n    END AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval1'',\n        base.declaration->>''eventDetails_otherAntecedentCause1Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 2\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    2 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause2'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause2''\n      ELSE base.declaration->>''eventDetails_antecedentCause2''\n    END AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval2'',\n        base.declaration->>''eventDetails_otherAntecedentCause2Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 3\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    3 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause3'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause3''\n      ELSE base.declaration->>''eventDetails_antecedentCause3''\n    END AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval3'',\n        base.declaration->>''eventDetails_otherAntecedentCause3Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 4\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    4 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause4'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause4''\n      ELSE base.declaration->>''eventDetails_antecedentCause4''\n    END AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval4'',\n        base.declaration->>''eventDetails_otherAntecedentCause4Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 5\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    5 AS \"LineNb\",\n    base.declaration->>''eventDetails_otherSignificantCondition'' AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_signific', NULL);      
INSERT INTO SYSTEM_LOB_STREAM VALUES(91, 1, 'antConditionInterval'',\n        base.declaration->>''eventDetails_otherSignificantConditionInterval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n) t\nWHERE NULLIF(TRIM(\"TextLine\"), '''') IS NOT NULL\nORDER BY \"CertificateKey\", \"LineNb\";\n"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"CertificateKey","table.cell_column":"LineNb"},"parameters":[],"dashboard_id":14}', NULL);         
INSERT INTO SYSTEM_LOB_STREAM VALUES(92, 0, '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":14,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"MEDCOD","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH base AS (\n  SELECT DISTINCT ON (ea.event_id) *\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND ea.declaration->>''irisOutput_ucCode'' IS NULL\n  ORDER BY ea.event_id, ea.created_at DESC\n)\n\nSELECT *\nFROM (\n  -- Line 0 (Immediate)\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    0 AS \"LineNb\",\n    COALESCE(\n      base.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n      NULLIF(base.declaration->>''eventDetails_immediateCauseOfDeath'', '''')\n    ) AS \"TextLine\",\n    COALESCE(\n      base.declaration->''eventDetails_immediateCauseOfDeath''->>''value'',\n      ''''::text\n    ) AS \"CodeLine\",\n    NULLIF(\n      TRIM(\n        COALESCE(base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''numericValue'', '''') || '' '' ||\n        COALESCE(base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''unit'', '''')\n      ),\n      ''''\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 1\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    1 AS \"LineNb\",\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause1''->>''label'',\n      NULLIF(base.declaration->>''eventDetails_antecedentCause1'', '''')\n    ) AS \"TextLine\",\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause1''->>''value'',\n      ''''::text\n    ) AS \"CodeLine\",\n    NULLIF(\n      TRIM(\n        COALESCE(base.declaration->''eventDetails_antecedentCauseInterval1''->>''numericValue'', '''') || '' '' ||\n        COALESCE(base.declaration->''eventDetails_antecedentCauseInterval1''->>''unit'', '''')\n      ),\n      ''''\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 2\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    2 AS \"LineNb\",\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause2''->>''label'',\n      NULLIF(base.declaration->>''eventDetails_antecedentCause2'', '''')\n    ) AS \"TextLine\",\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause2''->>''value'',\n      ''''::text\n    ) AS \"CodeLine\",\n    NULLIF(\n      TRIM(\n        COALESCE(base.declaration->''eventDetails_antecedentCauseInterval2''->>''numericValue'', '''') || '' '' ||\n        COALESCE(base.declaration->''eventDetails_antecedentCauseInterval2''->>''unit'', '''')\n      ),\n      ''''\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 3\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    3 AS \"LineNb\",\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause3''->>''label'',\n      NULLIF(base.declaration->>''eventDetails_antecedentCause3'', '''')\n    ) AS \"TextLine\",\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause3''->>''value'',\n      ''''::text\n    ) AS \"CodeLine\",\n    NULLIF(\n      TRIM(\n        COALESCE(base.declaration->''eventDetails_antecedentCauseInterval3''->>''numericValue'', '''') || '' '' ||\n        COALESCE(base.declaration->''eventDetails_antecedentCauseInterval3''->>''unit'', '''')\n      ),\n      ''''\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 4\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    4 AS \"LineNb\",\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause4''->>''label'',\n      NULLIF(base.declaration->>''eventDetails_antecedentCause4'', '''')\n    ) AS \"TextLine\",\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause4''->>''value'',\n      ''''::text\n    ) AS \"CodeLine\",\n    NULLIF(\n      TRIM(\n        COALESCE(base.declaration->''eventDetails_antecedentCauseInterval4''->>''numericValue'', '''')', NULL);               
INSERT INTO SYSTEM_LOB_STREAM VALUES(92, 1, ' || '' '' ||\n        COALESCE(base.declaration->''eventDetails_antecedentCauseInterval4''->>''unit'', '''')\n      ),\n      ''''\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 5 (Other significant condition)\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    5 AS \"LineNb\",\n    NULLIF(base.declaration->>''eventDetails_otherSignificantCondition'', '''') AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      TRIM(\n        COALESCE(base.declaration->''eventDetails_significantConditionInterval''->>''numericValue'', '''') || '' '' ||\n        COALESCE(base.declaration->''eventDetails_significantConditionInterval''->>''unit'', '''')\n      ),\n      ''''\n    ) AS \"IntervalLine\"\n  FROM base\n) t\nWHERE NULLIF(TRIM(\"TextLine\"), '''') IS NOT NULL\nORDER BY \"CertificateKey\", \"LineNb\";\n"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"CertificateKey","table.cell_column":"LineNb"},"parameters":[],"dashboard_id":14}', NULL);          
INSERT INTO "PUBLIC"."REVISION" VALUES
(741, 'Card', 161, 1, TIMESTAMP WITH TIME ZONE '2026-02-18 10:39:21.88027+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"IDENT","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT\n  ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n  to_char((ea.declaration->>''deceased_dob'')::date, ''DD/MM/YYYY'') AS \"DateBirth\",\n  to_char((ea.declaration->>''deceased_eventDate'')::date, ''DD/MM/YYYY'') AS \"DateDeath\",\n  ea.declaration->>''deceased_gender'' AS \"Sex\"\n\nFROM analytics.event_actions ea\n\nWHERE \n  -- Only unique registration_numbers\n  ea.registration_number IN (\n      SELECT registration_number\n      FROM analytics.event_actions\n      GROUP BY registration_number\n      HAVING COUNT(*) = 1\n  )\n  AND\n  -- Only rows where irisOutput_ucCode === ''Default''\n  (ea.declaration->>''irisOutput_ucCode'') = ''Default'';\n"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"Deceased DOB","table.cell_column":"Deceased age"},"parameters":[],"dashboard_id":14}', FALSE, FALSE, NULL, FALSE, 'v0.56.4 (aeaacd0)'),
(742, 'Card', 161, 1, TIMESTAMP WITH TIME ZONE '2026-02-18 11:06:02.768304+00', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"IDENT","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT DISTINCT ON (d.event_id)\n  d.\"CertificateKey\",\n  ''''::text AS \"LastChange\",\n  to_char(d.\"DateBirth\", ''YYYY-MM-DD'') AS \"DateBirth\",\n  to_char(d.\"DateDeath\", ''YYYY-MM-DD'') AS \"DateDeath\",\n  EXTRACT(YEAR FROM age(d.\"DateDeath\", d.\"DateBirth\"))::int || '' Years'' AS \"Age\",\n  d.\"Sex\"\nFROM (\n  SELECT\n    ea.event_id,\n    ea.created_at,\n    ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    NULLIF(ea.declaration->>''deceased_dob'','''')::date AS \"DateBirth\",\n    NULLIF(ea.declaration->>''deceased_eventDate'','''')::date AS \"DateDeath\",\n    ea.declaration->>''deceased_gender'' AS \"Sex\"\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND ea.declaration->>''irisOutput_ucCode'' IS NULL\n) d\nORDER BY d.event_id, d.created_at DESC;\n"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"Deceased DOB","table.cell_column":"Deceased age"},"parameters":[],"dashboard_id":14}', FALSE, FALSE, NULL, FALSE, 'v0.56.4 (aeaacd0)'),
