(763, 'Card', 161, 1, TIMESTAMP WITH TIME ZONE '2026-04-30 09:35:42.312724+01', '{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":null,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"IDENT","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT DISTINCT ON (d.event_id)\n  d.\"CertificateKey\",\n  ''''::text AS \"LastChange\",\n  to_char(d.\"DateBirth\"::timestamp, ''DD/MM/YYYY'') AS \"DateBirth\",\n  to_char(d.\"DateDeath\"::timestamp, ''DD/MM/YYYY'') AS \"DateDeath\",\n  CASE\n    WHEN d.\"DateBirth\" IS NOT NULL AND d.\"DateDeath\" IS NOT NULL\n      THEN EXTRACT(YEAR FROM age(d.\"DateDeath\", d.\"DateBirth\"))::int || '' Years''\n    WHEN d.\"DeclaredAge\" IS NOT NULL\n      THEN d.\"DeclaredAge\"::text || '' Years''\n    ELSE NULL\n  END AS \"Age\",\n  d.\"Sex\",\n  d.\"Comments\"\nFROM (\n  SELECT\n    ea.event_id,\n    ea.created_at,\n    ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    NULLIF(ea.declaration->>''deceased_dob'','''')::date AS \"DateBirth\",\n    NULLIF(ea.declaration->>''deceased_eventDate'','''')::date AS \"DateDeath\",\n    NULLIF(ea.declaration->''deceased_age''->>''age'','''')::int AS \"DeclaredAge\",\n    CASE COALESCE(NULLIF(ea.declaration->>''deceased_gender'',''''),''9'')\n      WHEN ''1'' THEN ''Male''\n      WHEN ''2'' THEN ''Female''\n      WHEN ''8'' THEN ''Other''\n      ELSE ''Unknown''\n    END AS \"Sex\",\n    NULLIF(ea.annotation->>''review_comment'', '''') AS \"Comments\"\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND ea.declaration->>''irisOutput_ucCode'' IS NULL\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions r\n      WHERE r.event_id = ea.event_id\n        AND r.action_type = ''REGISTER''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions a\n      WHERE a.event_id = ea.event_id\n        AND a.action_type = ''ARCHIVE''\n    )\n) d\nORDER BY d.event_id, d.created_at DESC;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"Deceased DOB","table.cell_column":"Deceased age"},"parameters":[],"dashboard_id":14}', FALSE, FALSE, NULL, FALSE, 'v0.56.4 (aeaacd0)');             
