WHEN base.declaration->''eventDetails_causeOfDeathOther_symptom_eight''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathOther_symptom_eight_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathOther_symptom_eight''->>''label'', '''')\n        END\n      ),\n      ', NULL); 
