INSERT INTO SYSTEM_LOB_STREAM VALUES(109, 0, '{"description":null,"archived":false,"collection_position":1,"source_card_id":null,"table_id":null,"result_metadata":[{"name":"location_id","database_type":"text","base_type":"type/Text","display_name":"location_id","field_ref":["field","location_id",{"base-type":"type/Text"}],"semantic_type":null},{"name":"location_name","database_type":"text","base_type":"type/Text","display_name":"location_name","field_ref":["field","location_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"CertificateKey","database_type":"text","base_type":"type/Text","display_name":"CertificateKey","field_ref":["field","CertificateKey",{"base-type":"type/Text"}],"semantic_type":null},{"name":"LastChange","database_type":"text","base_type":"type/Text","display_name":"LastChange","field_ref":["field","LastChange",{"base-type":"type/Text"}],"semantic_type":null},{"name":"DateBirth","database_type":"text","base_type":"type/Text","display_name":"DateBirth","field_ref":["field","DateBirth",{"base-type":"type/Text"}],"semantic_type":null},{"name":"DateDeath","database_type":"text","base_type":"type/Text","display_name":"DateDeath","field_ref":["field","DateDeath",{"base-type":"type/Text"}],"semantic_type":null},{"name":"Age","database_type":"text","base_type":"type/Text","display_name":"Age","field_ref":["field","Age",{"base-type":"type/Text"}],"semantic_type":null},{"name":"Sex","database_type":"text","base_type":"type/Text","display_name":"Sex","semantic_type":"type/Category","field_ref":["field","Sex",{"base-type":"type/Text"}]},{"name":"Comments","database_type":"text","base_type":"type/Text","display_name":"Comments","semantic_type":"type/Comment","field_ref":["field","Comments",{"base-type":"type/Text"}]}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":7,"query_type":"native","name":"IDENT Model","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT DISTINCT ON (d.event_id)\n  d.location_id,\n  d.location_name,\n  d.\"CertificateKey\",\n  ''''::text AS \"LastChange\",\n  to_char(d.\"DateBirth\"::timestamp, ''DD/MM/YYYY'') AS \"DateBirth\",\n  to_char(d.\"DateDeath\"::timestamp, ''DD/MM/YYYY'') AS \"DateDeath\",\n  CASE\n    WHEN d.\"DateBirth\" IS NOT NULL AND d.\"DateDeath\" IS NOT NULL\n      THEN EXTRACT(YEAR FROM age(d.\"DateDeath\", d.\"DateBirth\"))::int || '' Years''\n    WHEN d.\"DeclaredAge\" IS NOT NULL\n      THEN d.\"DeclaredAge\"::text || '' Years''\n    ELSE NULL\n  END AS \"Age\",\n  d.\"Sex\",\n  d.\"Comments\"\nFROM (\n  SELECT\n    ea.event_id,\n    ea.created_at,\n    ea.created_at_location AS location_id,\n    l.name AS location_name,\n    ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    NULLIF(ea.declaration->>''deceased_dob'','''')::date AS \"DateBirth\",\n    NULLIF(ea.declaration->>''deceased_eventDate'','''')::date AS \"DateDeath\",\n    NULLIF(ea.declaration->''deceased_age''->>''age'','''')::int AS \"DeclaredAge\",\n    CASE COALESCE(NULLIF(ea.declaration->>''deceased_gender'',''''),''9'')\n      WHEN ''1'' THEN ''Male''\n      WHEN ''2'' THEN ''Female''\n      WHEN ''8'' THEN ''Other''\n      ELSE ''Unknown''\n    END AS \"Sex\",\n    NULLIF(ea.annotation->>''review_comment'', '''') AS \"Comments\"\n  FROM analytics.event_actions ea\n  LEFT JOIN analytics.locations l\n    ON ea.created_at_location = l.id\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND (\n      ea.declaration->>''irisOutput_ucCode'' IS NULL\n      OR ea.declaration->>''irisOutput_ucCode'' = ''None''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions r\n      WHERE r.event_id = ea.event_id\n        AND r.action_type = ''REGISTER''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions a\n      WHERE a.event_id = ea.event_id\n        AND a.action_type = ''ARCHIVE''\n    )\n) d\nORDER BY d.event_id, d.created_at DESC;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.pivot_column":"LastChange"', NULL);          
INSERT INTO SYSTEM_LOB_STREAM VALUES(109, 1, ',"table.cell_column":"Comments"},"parameters":[],"dashboard_id":null}', NULL);   
INSERT INTO SYSTEM_LOB_STREAM VALUES(110, 0, '{"description":null,"archived":false,"collection_position":2,"source_card_id":null,"table_id":null,"result_metadata":[{"name":"location_id","database_type":"text","base_type":"type/Text","display_name":"location_id","field_ref":["field","location_id",{"base-type":"type/Text"}],"semantic_type":null},{"name":"location_name","database_type":"text","base_type":"type/Text","display_name":"location_name","field_ref":["field","location_name",{"base-type":"type/Text"}],"semantic_type":null},{"name":"CertificateKey","database_type":"text","base_type":"type/Text","display_name":"CertificateKey","field_ref":["field","CertificateKey",{"base-type":"type/Text"}],"semantic_type":null},{"name":"LineNb","database_type":"int4","base_type":"type/Integer","display_name":"LineNb","field_ref":["field","LineNb",{"base-type":"type/Integer"}],"semantic_type":null},{"name":"TextLine","database_type":"text","base_type":"type/Text","display_name":"TextLine","field_ref":["field","TextLine",{"base-type":"type/Text"}],"semantic_type":null},{"name":"CodeLine","database_type":"text","base_type":"type/Text","display_name":"CodeLine","field_ref":["field","CodeLine",{"base-type":"type/Text"}],"semantic_type":null},{"name":"IntervalLine","database_type":"text","base_type":"type/Text","display_name":"IntervalLine","field_ref":["field","IntervalLine",{"base-type":"type/Text"}],"semantic_type":null}],"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":7,"query_type":"native","name":"MEDCOD Model","type":"model","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH latest_declare AS (\n  SELECT *\n  FROM (\n    SELECT\n      ea.*,\n      ea.created_at_location AS location_id,\n      l.name AS location_name,\n      ROW_NUMBER() OVER (\n        PARTITION BY ea.event_id\n        ORDER BY ea.created_at DESC, ea.id DESC\n      ) AS rn\n    FROM analytics.event_actions ea\n    LEFT JOIN analytics.locations l\n      ON ea.created_at_location = l.id\n    WHERE ea.action_type = ''DECLARE''\n  ) x\n  WHERE x.rn = 1\n),\nbase AS (\n  SELECT ld.*\n  FROM latest_declare ld\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM analytics.event_actions r\n    WHERE r.event_id = ld.event_id\n      AND r.registration_number IS NOT NULL\n      AND NULLIF(r.declaration->>''irisOutput_ucCode'', '''') IS NOT NULL\n  )\n  AND NOT EXISTS (\n    SELECT 1\n    FROM analytics.event_actions a\n    WHERE a.event_id = ld.event_id\n      AND a.action_type = ''ARCHIVE''\n  )\n)\n\nSELECT\n  t.location_id,\n  t.location_name,\n  t.\"CertificateKey\",\n  t.\"LineNb\",\n  t.\"TextLine\",\n  t.\"CodeLine\",\n  t.\"IntervalLine\"\nFROM (\n  -- causeOfDeathA\n  SELECT\n    base.location_id,\n    base.location_name,\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    0 AS \"LineNb\",\n    NULLIF(\n      concat_ws(\n        ''; '',\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_one''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_one_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_one''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_two''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_two_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_two''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_three''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_three_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_three''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_four''->>''value'' = ''