(912, 'Card', 177, 1, TIMESTAMP WITH TIME ZONE '2026-06-03 10:11:45.518329+02', U&'{"description":null,"archived":false,"collection_position":null,"source_card_id":null,"table_id":14,"card_schema":22,"database_id":2,"enable_embedding":false,"collection_id":8,"query_type":"native","name":"Major causes \2014 females","type":"question","embedding_params":null,"cache_ttl":null,"dataset_query":{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH causes AS (\\n  SELECT\\n    (\\n      declaration #>> ARRAY[''irisOutput_ucCode'']\\n    ) AS uc_code,\\n    (\\n      declaration #>> ARRAY[\\n        ''eventDetails_causeOfDeathA_symptom_one'',\\n        ''label''\\n      ]\\n    ) AS symptom,\\n    COUNT(*) AS count,\\n    ROUND(\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\n      2\\n    ) AS percentage\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n  GROUP BY 1, 2\\n),\\n\\ntop10 AS (\\n  SELECT *\\n  FROM causes\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\n  LIMIT 10\\n),\\n\\nranked AS (\\n  SELECT\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\n    uc_code,\\n    symptom,\\n    count,\\n    percentage\\n  FROM top10\\n)\\n\\nSELECT\\n  rank AS \\"RANK\\",\\n  uc_code AS \\"declaration \2192 irisOutput_ucCode\\",\\n  symptom AS \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\",\\n  count,\\n  percentage\\nFROM ranked\\n\\nUNION ALL\\n\\nSELECT\\n  ''Total (Top 10)'',\\n  '''',\\n  '''',\\n  SUM(count),\\n  ROUND(SUM(percentage), 2)\\nFROM ranked;"}},"parameter_mappings":[],"display":"table","archived_directly":false,"collection_preview":true,"visualization_settings":{"table.column_formatting":[],"table.pivot":false,"table.row_index":false,"table.pivot_column":"declaration \2192 irisOutput_ucCode","table.cell_column":"count","table.column_widths":[130],"column_settings":{"[\\"name\\",\\"declaration \2192 irisOutput_ucCode\\"]":{"column_title":"ICD-10","t