(X'61943f45d74982076c89d7db281a05fd145598c8c0a96dd30851266e4a053cd7', 11, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    id,\n    parent_id,\n    name,\n    name::text AS path,\n    1 AS level                  -- root = 1\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '','' || l.name,\n    lp.level + 1\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n)\nSELECT l.*, lp.path AS full_path, lp.level\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
