(X'8b2ea3403607cffc76e53a17d3b12766aef8868eb5d8515daaef811d7111ce7a', 21, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    l.name::text AS path,\n    1 AS level,\n    CASE\n      WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.id)\n      ELSE ''{}''::jsonb\n    END AS level_map\n  FROM analytics.locations l\n  LEFT JOIN analytics.location_levels ll ON ll.level = 1\n  WHERE l.parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '','' || l.name,\n    lp.level + 1 AS level,\n    lp.level_map\n      || CASE\n           WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.id)\n           ELSE ''{}''::jsonb\n         END AS level_map\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lp.level + 1\n)\nSELECT\n  l.*,\n  lp.path  AS full_path,\n  lp.level,\n  ll.id    AS level_id,\n  lp.level_map\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll ON ll.level = lp.level;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');              
