(X'fee023b6cc7a595be28d7fba788a4e7e7c9d34b56e27fc9adc2446b5681a00c4', 45, '{"database":2,"type":"native","native":{"template-tags":{},"query":"-- Creates a view with one column per location_levels.id (lvl_<id>)\nDO $$\nDECLARE\n  cols text;\n  sql  text;\nBEGIN\n  SELECT string_agg(\n           format(''(lp.level_map->>%L)::bigint AS lvl_%s'', ll.id::text, ll.id),\n           '', '' ORDER BY ll.level\n         )\n    INTO cols\n    FROM analytics.location_levels ll;\n\n  sql := format($f$\n    CREATE OR REPLACE VIEW analytics.location_hierarchy_pivot AS\n    WITH RECURSIVE location_path AS (\n      SELECT\n        l.id,\n        l.parent_id,\n        l.name,\n        l.name::text AS path,\n        1 AS level,\n        CASE\n          WHEN ll1.id IS NOT NULL THEN jsonb_build_object(ll1.id::text, l.id)\n          ELSE ''{}''::jsonb\n        END AS level_map\n      FROM analytics.locations l\n      LEFT JOIN analytics.location_levels ll1 ON ll1.level = 1\n      WHERE l.parent_id IS NULL\n\n      UNION ALL\n\n      SELECT\n        l.id,\n        l.parent_id,\n        l.name,\n        lp.path || '','' || l.name,\n        lp.level + 1,\n        lp.level_map\n          || CASE\n               WHEN ll2.id IS NOT NULL THEN jsonb_build_object(ll2.id::text, l.id)\n               ELSE ''{}''::jsonb\n             END\n      FROM analytics.locations l\n      JOIN location_path lp ON l.parent_id = lp.id\n      LEFT JOIN analytics.location_levels ll2 ON ll2.level = lp.level + 1\n    )\n    SELECT\n      l.*,\n      lp.path  AS full_path,\n      lp.level,\n      ll.id    AS level_id,\n      %s\n    FROM location_path lp\n    JOIN analytics.locations l ON l.id = lp.id\n    LEFT JOIN analytics.location_levels ll ON ll.level = lp.level\n    ORDER BY l.id;\n  $f$, cols);\n\n  EXECUTE sql;\nEND $$;\n\n-- Usage:\n-- SELECT * FROM analytics.location_hierarchy_pivot;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
