(X'ecc4e838a949d15df39ebd38f524e15623f4da1afb3f93ff70289f85c06d9aae', 13, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    l.name::text AS path,\n    1 AS level,\n    CASE\n      WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.id)\n      ELSE ''{}''::jsonb\n    END AS level_map\n  FROM analytics.locations l\n  LEFT JOIN analytics.location_levels ll ON ll.level = 1\n  WHERE l.parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '','' || l.name,\n    lp.level + 1 AS level,\n    lp.level_map\n      || CASE\n           WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.name::text, l.id)\n           ELSE ''{}''::jsonb\n         END AS level_map\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lp.level + 1\n)\nSELECT\n  l.*,\n  lp.path  AS full_path,\n  lp.level,\n  ll.id    AS level_id,\n  lp.level_map\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll ON ll.level = lp.level;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'0ae802bd84d2d20958c10129d4fba126a8591cb46b0ade1a4ca4672cfe98fdde', 24, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    l.name::text AS path,\n    1 AS level,\n    CASE\n      WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.id)\n      ELSE ''{}''::jsonb\n    END AS level_map\n  FROM analytics.locations l\n  LEFT JOIN analytics.location_levels ll ON ll.level = 1\n  WHERE l.parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '','' || l.name,\n    lp.level + 1 AS level,\n    lp.level_map\n      || CASE\n           WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.name)\n           ELSE ''{}''::jsonb\n         END AS level_map\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lp.level + 1\n)\nSELECT\n  l.*,\n  lp.path  AS full_path,\n  lp.level,\n  ll.id    AS level_id,\n  lp.level_map\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll ON ll.level = lp.level;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'88edffec56b42a3a782e720d809a1eee7349cb093c29bca419e93e9b866558ed', 13, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    l.name::text AS path,\n    1 AS level,\n    CASE\n      WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.name)\n      ELSE ''{}''::jsonb\n    END AS level_map\n  FROM analytics.locations l\n  LEFT JOIN analytics.location_levels ll ON ll.level = 1\n  WHERE l.parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '','' || l.name,\n    lp.level + 1 AS level,\n    lp.level_map\n      || CASE\n           WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.name)\n           ELSE ''{}''::jsonb\n         END AS level_map\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lp.level + 1\n)\nSELECT\n  l.*,\n  lp.path  AS full_path,\n  lp.level,\n  ll.id    AS level_id,\n  lp.level_map\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll ON ll.level = lp.level;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');             
INSERT INTO "PUBLIC"."QUERY" VALUES
(X'7bc02a27d24ae220eab5c428e549c5b5b2dc79d008be7c769e4323bbccd9f54f', 35, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    l.name::text AS path,\n    1 AS level,\n    CASE\n      WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.name)\n      ELSE ''{}''::jsonb\n    END AS level_map\n  FROM analytics.locations l\n  LEFT JOIN analytics.location_levels ll ON ll.level = 1\n  WHERE l.parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '','' || l.name,\n    lp.level + 1 AS level,\n    lp.level_map\n      || CASE\n           WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.name)\n           ELSE ''{}''::jsonb\n         END AS level_map\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lp.level + 1\n),\npivot AS (\n  SELECT\n    lp.id,\n    MAX(j.value) FILTER (WHERE ll2.level = 1)  AS level_1_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 2)  AS level_2_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 3)  AS level_3_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 4)  AS level_4_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 5)  AS level_5_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 6)  AS level_6_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 7)  AS level_7_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 8)  AS level_8_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 9)  AS level_9_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 10) AS level_10_name\n  FROM location_path lp\n  CROSS JOIN LATERAL jsonb_each_text(lp.level_map) AS j(key, value)\n  JOIN analytics.location_levels ll2 ON ll2.id::text = j.key\n  GROUP BY lp.id\n)\nSELECT\n  l.*,\n  lp.path  AS full_path,\n  lp.level,\n  ll.id    AS level_id,\n  lp.level_map,\n  p.level_1_name,  p.level_2_name,  p.level_3_name,  p.level_4_name,  p.level_5_name,\n  p.level_6_name,  p.level_7_name,  p.level_8_name,  p.level_9_name,  p.level_10_name\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll ON ll.level = lp.level\nLEFT JOIN pivot p ON p.id = l.id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'e2cb470e09a0c644ab911469b85ed1dd7a7e53167817d104d828994eb490e3ed', 6, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{},"query":"WITH RECURSIVE location_path AS (\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    l.name::text AS path,\n    1 AS level,\n    CASE\n      WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.name)\n      ELSE ''{}''::jsonb\n    END AS level_map\n  FROM analytics.locations l\n  LEFT JOIN analytics.location_levels ll ON ll.level = 1\n  WHERE l.parent_id IS NULL\n\n  UNION ALL\n\n  SELECT\n    l.id,\n    l.parent_id,\n    l.name,\n    lp.path || '','' || l.name,\n    lp.level + 1 AS level,\n    lp.level_map\n      || CASE\n           WHEN ll.id IS NOT NULL THEN jsonb_build_object(ll.id::text, l.name)\n           ELSE ''{}''::jsonb\n         END AS level_map\n  FROM analytics.locations l\n  JOIN location_path lp ON l.parent_id = lp.id\n  LEFT JOIN analytics.location_levels ll ON ll.level = lp.level + 1\n),\npivot AS (\n  SELECT\n    lp.id,\n    MAX(j.value) FILTER (WHERE ll2.level = 1)  AS level_1_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 2)  AS level_2_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 3)  AS level_3_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 4)  AS level_4_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 5)  AS level_5_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 6)  AS level_6_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 7)  AS level_7_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 8)  AS level_8_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 9)  AS level_9_name,\n    MAX(j.value) FILTER (WHERE ll2.level = 10) AS level_10_name\n  FROM location_path lp\n  CROSS JOIN LATERAL jsonb_each_text(lp.level_map) AS j(key, value)\n  JOIN analytics.location_levels ll2 ON ll2.id::text = j.key\n  GROUP BY lp.id\n)\nSELECT\n  l.*,\n  lp.path  AS full_path,\n  lp.level,\n  ll.id    AS level_id,\n  lp.level_map,\n  p.level_1_name,  p.level_2_name,  p.level_3_name,  p.level_4_name,  p.level_5_name,\n  p.level_6_name,  p.level_7_name,  p.level_8_name,  p.level_9_name,  p.level_10_name\nFROM analytics.locations l\nJOIN location_path lp ON l.id = lp.id\nLEFT JOIN analytics.location_levels ll ON ll.level = lp.level\nLEFT JOIN pivot p ON p.id = l.id;"},"viz-settings":{"table.pivot_column":"created_at","table.cell_column":"valid_until"},"database":2}'); 
