(X'21d22284c0d6b7cb7575a621bf3048275e4c9dea66587edbfedb6e8bcbb10454', 18, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE levels AS (\n    -- root = 1, children increment\n    SELECT id, parent_id, 1 AS level\n    FROM analytics.locations\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT l.id, l.parent_id, lv.level + 1\n    FROM analytics.locations l\n    JOIN levels lv ON l.parent_id = lv.id\n),\n-- ancestor/descendant closure: every node is ancestor of itself and all its descendants\nclosure AS (\n    SELECT id AS ancestor_id, id AS descendant_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT c.ancestor_id, l.id AS descendant_id\n    FROM closure c\n    JOIN analytics.locations l ON l.parent_id = c.descendant_id\n),\n-- counts at leaf/origin locations by year\ncounts AS (\n    SELECT ea.created_at_location AS location_id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.event_actions ea\n    WHERE ea.action_type = ''REGISTER''\n      AND ea.event_type  = ''birth''\n      AND ea.created_at IS NOT NULL\n      AND ea.created_at_location IS NOT NULL\n    GROUP BY ea.created_at_location, year\n),\n-- roll up descendant counts to each ancestor (this is the named query)\nbirth_registrations_per_location AS (\n    SELECT c.ancestor_id AS location_id,\n           cnt.year,\n           SUM(cnt.cnt) AS register_count\n    FROM closure c\n    JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY c.ancestor_id, cnt.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count,\n    lv.level,\n    ll.name AS level_name\nFROM analytics.locations l\nJOIN analytics.location_statistics s\n  ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br\n  ON br.location_id = l.id AND br.year = s.year\nLEFT JOIN levels lv\n  ON lv.id = l.id\nLEFT JOIN analytics.location_levels ll\n  ON ll.level = lv.level\nORDER BY s.year DESC, register_count DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'6fa9e48ce94f35bed566c93ab3ab9093268bd5b608275f11e06caca533c93c0b', 20, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{},"query":"WITH RECURSIVE levels AS (\n    -- root = 1, children increment\n    SELECT id, parent_id, 1 AS level\n    FROM analytics.locations\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT l.id, l.parent_id, lv.level + 1\n    FROM analytics.locations l\n    JOIN levels lv ON l.parent_id = lv.id\n),\n-- ancestor/descendant closure: every node is ancestor of itself and all its descendants\nclosure AS (\n    SELECT id AS ancestor_id, id AS descendant_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT c.ancestor_id, l.id AS descendant_id\n    FROM closure c\n    JOIN analytics.locations l ON l.parent_id = c.descendant_id\n),\n-- counts at leaf/origin locations by year\ncounts AS (\n    SELECT ea.created_at_location AS location_id,\n           EXTRACT(YEAR FROM ea.created_at)::int AS year,\n           COUNT(*) AS cnt\n    FROM analytics.event_actions ea\n    WHERE ea.action_type = ''REGISTER''\n      AND ea.event_type  = ''birth''\n      AND ea.created_at IS NOT NULL\n      AND ea.created_at_location IS NOT NULL\n    GROUP BY ea.created_at_location, year\n),\n-- roll up descendant counts to each ancestor (this is the named query)\nbirth_registrations_per_location AS (\n    SELECT c.ancestor_id AS location_id,\n           cnt.year,\n           SUM(cnt.cnt) AS register_count\n    FROM closure c\n    JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY c.ancestor_id, cnt.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count,\n    lv.level,\n    ll.name AS level_name\nFROM analytics.locations l\nJOIN analytics.location_statistics s\n  ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br\n  ON br.location_id = l.id AND br.year = s.year\nLEFT JOIN levels lv\n  ON lv.id = l.id\nLEFT JOIN analytics.location_levels ll\n  ON ll.level = lv.level\nORDER BY s.year DESC, register_count DESC;"},"viz-settings":{"graph.x_axis.scale":"ordinal","graph.dimensions":["name"],"table.pivot_column":"crude_birth_rate","table.cell_column":"year","graph.metrics":[]},"database":2}'); 
