INSERT INTO SYSTEM_LOB_STREAM VALUES(262, 0, U&'{"type":"native","native":{"query":"SELECT\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''deceased_certificateKey'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 deceased_certificateKey\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''deceased_country'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 deceased_country\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''deceased_deceasedAge'' ] :: text [ ]\\n  ) :: decimal AS \\"declaration \2192 deceased_deceasedAge\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''deceased_dob'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 deceased_dob\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''deceased_eventDate'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 deceased_eventDate\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''deceased_fijiAdmin1'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 deceased_fijiAdmin1\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''deceased_gender'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 deceased_gender\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_antecedentCause2'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 eventDetails_antecedentCause2\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_antecedentCause4'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 eventDetails_antecedentCause4\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_immediateCauseOfDeath'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 eventDetails_immediateCauseOfDeath\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_immediateCauseOfDeathInterval'' ] :: text [ ]\\n  ) :: decimal AS \\"declaration \2192 eventDetails_immediateCauseOfDeathInterval\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_mannerOfDeath'' ] :: text [ ]\\n  ) :: decimal AS \\"declaration \2192 eventDetails_mannerOfDeath\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_otherAntecedentCause1Interval'' ] :: text [ ]\\n  ) :: decimal AS \\"declaration \2192 eventDetails_otherAntecedentCause1Interval\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_otherAntecedentCause2Interval'' ] :: text [ ]\\n  ) :: decimal AS \\"declaration \2192 eventDetails_otherAntecedentCause2Interval\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_otherAntecedentCause3Interval'' ] :: text [ ]\\n  ) :: decimal AS \\"declaration \2192 eventDetails_otherAntecedentCause3Interval\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_otherAntecedentCause4Interval'' ] :: text [ ]\\n  ) :: decimal AS \\"declaration \2192 eventDetails_otherAntecedentCause4Interval\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_otherSignificantCondition'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 eventDetails_otherSignificantCondition\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_otherSignificantConditionInterval'' ] :: text [ ]\\n  ) :: decimal AS \\"declaration \2192 eventDetails_otherSignificantCondit_0704b7d0\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''irisOutput_comment'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 irisOutput_comment\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''irisOutput_multipleCodes'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 irisOutput_multipleCodes\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''irisOutput_selectedCodes'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 irisOutput_selectedCodes\\",\\n  (\\n    \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''irisOutput_ucCode'' ] :: text [ ]\\n  ) :: text AS \\"declaration \2192 irisOutput_ucCode\\",\\n  \\"analytics\\".\\"event_actions\\".\\"event_type\\" AS \\"event_type\\",\\n  \\"analytics\\".\\"e', NULL);   
INSERT INTO SYSTEM_LOB_STREAM VALUES(262, 1, 'vent_actions\".\"action_type\" AS \"action_type\",\n  \"analytics\".\"event_actions\".\"annotation\" AS \"annotation\",\n  \"analytics\".\"event_actions\".\"assigned_to\" AS \"assigned_to\",\n  \"analytics\".\"event_actions\".\"created_at\" AS \"created_at\",\n  \"analytics\".\"event_actions\".\"created_at_location\" AS \"created_at_location\",\n  \"analytics\".\"event_actions\".\"created_by\" AS \"created_by\",\n  \"analytics\".\"event_actions\".\"created_by_role\" AS \"created_by_role\",\n  \"analytics\".\"event_actions\".\"created_by_signature\" AS \"created_by_signature\",\n  \"analytics\".\"event_actions\".\"created_by_user_type\" AS \"created_by_user_type\",\n  \"analytics\".\"event_actions\".\"declared_at\" AS \"declared_at\",\n  \"analytics\".\"event_actions\".\"registered_at\" AS \"registered_at\",\n  \"analytics\".\"event_actions\".\"declaration\" AS \"declaration\",\n  \"analytics\".\"event_actions\".\"event_id\" AS \"event_id\",\n  \"analytics\".\"event_actions\".\"id\" AS \"id\",\n  \"analytics\".\"event_actions\".\"original_action_id\" AS \"original_action_id\",\n  \"analytics\".\"event_actions\".\"registration_number\" AS \"registration_number\",\n  \"analytics\".\"event_actions\".\"request_id\" AS \"request_id\",\n  \"analytics\".\"event_actions\".\"status\" AS \"status\",\n  \"analytics\".\"event_actions\".\"transaction_id\" AS \"transaction_id\",\n  \"analytics\".\"event_actions\".\"content\" AS \"content\"\nFROM\n  \"analytics\".\"event_actions\"\nLIMIT\n  1048575","template-tags":{}},"database":2,"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}', NULL);          
INSERT INTO "PUBLIC"."QUERY" VALUES
(X'aab143a16b0ea73e5ee1d4869c3d4dc581287b6c1ca45a34e5591bb0758aeb04', 20, SYSTEM_COMBINE_CLOB(262)),
(X'ce1aecbb417defeae3a614a6f04740b88ef3529cb50020e38648a350ea202a7f', 24, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH base AS (\n  SELECT *\n  FROM analytics.event_actions ea\n  WHERE ea.registration_number IN (\n      SELECT registration_number\n      FROM analytics.event_actions\n      GROUP BY registration_number\n      HAVING COUNT(*) = 1\n  )\n  AND (ea.declaration->>''irisOutput_ucCode'') = ''Default''\n)\n\nSELECT *\nFROM (\n  -- Line 0\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    0 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_immediateCauseOfDeath'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherImmediateCauseOfDeath''\n      ELSE base.declaration->>''eventDetails_immediateCauseOfDeath''\n    END AS \"TextLine\",\n    NULLIF(\n      base.declaration->>''eventDetails_immediateCauseOfDeathInterval'',\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 1\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    1 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause1'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause1''\n      ELSE base.declaration->>''eventDetails_antecedentCause1''\n    END AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval1'',\n        base.declaration->>''eventDetails_otherAntecedentCause1Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 2\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    2 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause2'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause2''\n      ELSE base.declaration->>''eventDetails_antecedentCause2''\n    END AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval2'',\n        base.declaration->>''eventDetails_otherAntecedentCause2Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 3\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    3 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause3'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause3''\n      ELSE base.declaration->>''eventDetails_antecedentCause3''\n    END AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval3'',\n        base.declaration->>''eventDetails_otherAntecedentCause3Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 4\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    4 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause4'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause4''\n      ELSE base.declaration->>''eventDetails_antecedentCause4''\n    END AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval4'',\n        base.declaration->>''eventDetails_otherAntecedentCause4Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 5\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    5 AS \"LineNb\",\n    base.declaration->>''eventDetails_otherSignificantCondition'' AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_significantConditionInterval'',\n        base.declaration->>''eventDetails_otherSignificantConditionInterval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n) t\nORDER BY \"CertificateKey\", \"LineNb\";\n"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');      
INSERT INTO SYSTEM_LOB_STREAM VALUES(263, 0, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{},"query":"WITH base AS (\n  SELECT *\n  FROM analytics.event_actions ea\n  WHERE ea.registration_number IN (\n      SELECT registration_number\n      FROM analytics.event_actions\n      GROUP BY registration_number\n      HAVING COUNT(*) = 1\n  )\n  AND (ea.declaration->>''irisOutput_ucCode'') = ''Default''\n)\n\nSELECT *\nFROM (\n  -- Line 0\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    0 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_immediateCauseOfDeath'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherImmediateCauseOfDeath''\n      ELSE base.declaration->>''eventDetails_immediateCauseOfDeath''\n    END AS \"TextLine\",\n    NULLIF(\n      base.declaration->>''eventDetails_immediateCauseOfDeathInterval'',\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 1\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    1 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause1'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause1''\n      ELSE base.declaration->>''eventDetails_antecedentCause1''\n    END AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval1'',\n        base.declaration->>''eventDetails_otherAntecedentCause1Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 2\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    2 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause2'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause2''\n      ELSE base.declaration->>''eventDetails_antecedentCause2''\n    END AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval2'',\n        base.declaration->>''eventDetails_otherAntecedentCause2Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 3\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    3 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause3'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause3''\n      ELSE base.declaration->>''eventDetails_antecedentCause3''\n    END AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval3'',\n        base.declaration->>''eventDetails_otherAntecedentCause3Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 4\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    4 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause4'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause4''\n      ELSE base.declaration->>''eventDetails_antecedentCause4''\n    END AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval4'',\n        base.declaration->>''eventDetails_otherAntecedentCause4Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 5\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    5 AS \"LineNb\",\n    base.declaration->>''eventDetails_otherSignificantCondition'' AS \"TextLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_significantConditionInterval'',\n        base.declaration->>''eventDetails_otherSignificantConditionInterval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n) t\nORDER BY \"CertificateKey\", \"LineNb\";\n"},"viz-settings":{"table.pivot_column":"CertificateKey","tab', NULL);            
