ause2'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause2''\n      ELSE base.declaration->>''eventDetails_antecedentCause2''\n    END AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval2'',\n        base.declaration->>''eventDetails_otherAntecedentCause2Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 3\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    3 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause3'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause3''\n      ELSE base.declaration->>''eventDetails_antecedentCause3''\n    END AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval3'',\n        base.declaration->>''eventDetails_otherAntecedentCause3Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 4\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    4 AS \"LineNb\",\n    CASE\n      WHEN base.declaration->>''eventDetails_antecedentCause4'' = ''OTHER''\n        THEN base.declaration->>''eventDetails_otherAntecedentCause4''\n      ELSE base.declaration->>''eventDetails_antecedentCause4''\n    END AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_antecedentCauseInterval4'',\n        base.declaration->>''eventDetails_otherAntecedentCause4Interval''\n      ),\n      ''''\n    )::int AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 5\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    5 AS \"LineNb\",\n    base.declaration->>''eventDetails_otherSignificantCondition'' AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      COALESCE(\n        base.declaration->>''eventDetails_significantConditionInterval'',\n        base.declaration->>''eventDetails_otherSignificantConditionInterval''\n      ),\n      ''''\n', NULL);
