INSERT INTO SYSTEM_LOB_STREAM VALUES(266, 0, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH base AS (\n  SELECT DISTINCT ON (ea.event_id) *\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND ea.declaration->>''irisOutput_ucCode'' IS NULL\n  ORDER BY ea.event_id, ea.created_at DESC\n)\n\nSELECT *\nFROM (\n  -- Line 0 (Immediate)\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    0 AS \"LineNb\",\n\n    COALESCE(\n      base.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n      NULLIF(base.declaration->>''eventDetails_immediateCauseOfDeath'', '''')\n    ) AS \"TextLine\",\n\n    COALESCE(\n      base.declaration->''eventDetails_immediateCauseOfDeath''->>''value'',\n      ''''::text\n    ) AS \"CodeLine\",\n\n    COALESCE(\n      NULLIF(\n        (base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''numericValue'') ||\n        '' '' ||\n        (base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''unit''),\n        '' ''\n      ),\n      NULLIF(base.declaration->>''eventDetails_immediateCauseOfDeathInterval'', '''')\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 1\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    1 AS \"LineNb\",\n\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause1''->>''label'',\n      NULLIF(base.declaration->>''eventDetails_antecedentCause1'', '''')\n    ) AS \"TextLine\",\n\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause1''->>''value'',\n      ''''::text\n    ) AS \"CodeLine\",\n\n    COALESCE(\n      NULLIF(\n        (base.declaration->''eventDetails_antecedentCauseInterval1''->>''numericValue'') ||\n        '' '' ||\n        (base.declaration->''eventDetails_antecedentCauseInterval1''->>''unit''),\n        '' ''\n      ),\n      NULLIF(\n        COALESCE(\n          base.declaration->>''eventDetails_antecedentCauseInterval1'',\n          base.declaration->>''eventDetails_otherAntecedentCause1Interval''\n        ),\n        ''''\n      )\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 2\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    2 AS \"LineNb\",\n\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause2''->>''label'',\n      NULLIF(base.declaration->>''eventDetails_antecedentCause2'', '''')\n    ) AS \"TextLine\",\n\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause2''->>''value'',\n      ''''::text\n    ) AS \"CodeLine\",\n\n    COALESCE(\n      NULLIF(\n        (base.declaration->''eventDetails_antecedentCauseInterval2''->>''numericValue'') ||\n        '' '' ||\n        (base.declaration->''eventDetails_antecedentCauseInterval2''->>''unit''),\n        '' ''\n      ),\n      NULLIF(\n        COALESCE(\n          base.declaration->>''eventDetails_antecedentCauseInterval2'',\n          base.declaration->>''eventDetails_otherAntecedentCause2Interval''\n        ),\n        ''''\n      )\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 3\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    3 AS \"LineNb\",\n\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause3''->>''label'',\n      NULLIF(base.declaration->>''eventDetails_antecedentCause3'', '''')\n    ) AS \"TextLine\",\n\n    COALESCE(\n      base.declaration->''eventDetails_antecedentCause3''->>''value'',\n      ''''::text\n    ) AS \"CodeLine\",\n\n    COALESCE(\n      NULLIF(\n        (base.declaration->''eventDetails_antecedentCauseInterval3''->>''numericValue'') ||\n        '' '' ||\n        (base.declaration->''eventDetails_antecedentCauseInterval3''->>''unit''),\n        '' ''\n      ),\n      NULLIF(\n        COALESCE(\n          base.declaration->>''eventDetails_antecedentCauseInterval3'',\n          base.declaration->>''eventDetails_otherAntecedentCause3Interval''\n        ),\n        ''''\n      )\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- Line 4\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    4 AS \"Line', NULL);            
