(X'430edf847cc747f4da928699609346e68264d2a1ff8d0da515fea5dbf47b7d6e', 28, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH base AS (\n  SELECT DISTINCT ON (ea.event_id) *\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND ea.declaration->>''irisOutput_ucCode'' IS NULL\n    AND EXISTS (\n      SELECT 1\n      FROM analytics.event_actions r\n      WHERE r.event_id = ea.event_id\n        AND r.action_type = ''REGISTER''\n    )\n  ORDER BY ea.event_id, ea.created_at DESC\n)\nSELECT\n  base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n\n  -- Line 0 (Immediate)\n  COALESCE(\n    base.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_immediateCauseOfDeath'', '''')\n  ) AS \"Cause A: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_immediateCauseOfDeath''->>''value'',\n    ''''::text\n  ) AS \"Cause A: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause A: Interval\",\n\n  -- Line 1\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause1''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause1'', '''')\n  ) AS \"Cause B: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause1''->>''value'',\n    ''''::text\n  ) AS \"Cause B: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval1''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval1''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause B: Interval\",\n\n  -- Line 2\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause2''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause2'', '''')\n  ) AS \"Cause C: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause2''->>''value'',\n    ''''::text\n  ) AS \"Cause C: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval2''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval2''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause C: Interval\",\n\n  -- Line 3\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause3''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause3'', '''')\n  ) AS \"Cause D: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause3''->>''value'',\n    ''''::text\n  ) AS \"Cause D: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval3''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval3''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause D: Interval\",\n\n  -- Line 4\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause4''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause4'', '''')\n  ) AS \"Cause E: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause4''->>''value'',\n    ''''::text\n  ) AS \"Cause E: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval4''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval4''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause E: Interval\",\n\nFROM base\nWHERE\n  COALESCE(\n    base.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n    base.declaration->''eventDetails_antecedentCause1''->>''label'',\n    base.declaration->''eventDetails_antecedentCause2''->>''label'',\n    base.declaration->''eventDetails_antecedentCause3''->>''label'',\n    base.declaration->''eventDetails_antecedentCause4''->>''label''\n  ) IS NOT NULL\nORDER BY \"CertificateKey\";"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');             
INSERT INTO "PUBLIC"."QUERY" VALUES
(X'530030ac747a2762a1d1e4fb2263f6668a41326e716fe553d01cda5d44117407', 33, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH base AS (\n  SELECT DISTINCT ON (ea.event_id) *\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND ea.declaration->>''irisOutput_ucCode'' IS NULL\n    AND EXISTS (\n      SELECT 1\n      FROM analytics.event_actions r\n      WHERE r.event_id = ea.event_id\n        AND r.action_type = ''REGISTER''\n    )\n  ORDER BY ea.event_id, ea.created_at DESC\n)\nSELECT\n  base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n\n  -- Line 0 (Immediate)\n  COALESCE(\n    base.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_immediateCauseOfDeath'', '''')\n  ) AS \"Cause A: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_immediateCauseOfDeath''->>''value'',\n    ''''::text\n  ) AS \"Cause A: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause A: Interval\",\n\n  -- Line 1\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause1''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause1'', '''')\n  ) AS \"Cause B: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause1''->>''value'',\n    ''''::text\n  ) AS \"Cause B: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval1''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval1''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause B: Interval\",\n\n  -- Line 2\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause2''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause2'', '''')\n  ) AS \"Cause C: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause2''->>''value'',\n    ''''::text\n  ) AS \"Cause C: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval2''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval2''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause C: Interval\",\n\n  -- Line 3\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause3''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause3'', '''')\n  ) AS \"Cause D: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause3''->>''value'',\n    ''''::text\n  ) AS \"Cause D: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval3''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval3''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause D: Interval\",\n\n  -- Line 4\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause4''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause4'', '''')\n  ) AS \"Cause E: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause4''->>''value'',\n    ''''::text\n  ) AS \"Cause E: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval4''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval4''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause E: Interval\"\n\nFROM base\nWHERE\n  COALESCE(\n    base.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n    base.declaration->''eventDetails_antecedentCause1''->>''label'',\n    base.declaration->''eventDetails_antecedentCause2''->>''label'',\n    base.declaration->''eventDetails_antecedentCause3''->>''label'',\n    base.declaration->''eventDetails_antecedentCause4''->>''label''\n  ) IS NOT NULL\nORDER BY \"CertificateKey\";"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');     
INSERT INTO SYSTEM_LOB_STREAM VALUES(273, 0, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH base AS (\n  SELECT DISTINCT ON (ea.event_id) *\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND EXISTS (\n      SELECT 1\n      FROM analytics.event_actions r\n      WHERE r.event_id = ea.event_id\n        AND r.action_type = ''REGISTER''\n    )\n  ORDER BY ea.event_id, ea.created_at DESC\n)\nSELECT\n  base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n\n  -- Underlying cause\n  base.declaration->>''irisOutput_ucCode'' AS \"Underlying cause: Code\",\n  CASE base.declaration->>''irisOutput_ucCode''\n    WHEN base.declaration->''eventDetails_immediateCauseOfDeath''->>''value''\n      THEN base.declaration->''eventDetails_immediateCauseOfDeath''->>''label''\n    WHEN base.declaration->''eventDetails_antecedentCause1''->>''value''\n      THEN base.declaration->''eventDetails_antecedentCause1''->>''label''\n    WHEN base.declaration->''eventDetails_antecedentCause2''->>''value''\n      THEN base.declaration->''eventDetails_antecedentCause2''->>''label''\n    WHEN base.declaration->''eventDetails_antecedentCause3''->>''value''\n      THEN base.declaration->''eventDetails_antecedentCause3''->>''label''\n    WHEN base.declaration->''eventDetails_antecedentCause4''->>''value''\n      THEN base.declaration->''eventDetails_antecedentCause4''->>''label''\n    ELSE NULL\n  END AS \"Underlying cause: Label\",\n\n  -- Cause A\n  COALESCE(\n    base.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_immediateCauseOfDeath'', '''')\n  ) AS \"Cause A: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_immediateCauseOfDeath''->>''value'',\n    ''''::text\n  ) AS \"Cause A: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause A: Interval\",\n\n  -- Cause B\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause1''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause1'', '''')\n  ) AS \"Cause B: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause1''->>''value'',\n    ''''::text\n  ) AS \"Cause B: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval1''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval1''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause B: Interval\",\n\n  -- Cause C\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause2''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause2'', '''')\n  ) AS \"Cause C: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause2''->>''value'',\n    ''''::text\n  ) AS \"Cause C: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval2''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval2''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause C: Interval\",\n\n  -- Cause D\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause3''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause3'', '''')\n  ) AS \"Cause D: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause3''->>''value'',\n    ''''::text\n  ) AS \"Cause D: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval3''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval3''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause D: Interval\",\n\n  -- Cause E\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause4''->>''label'',\n    NULLIF(base.declaration->>''eventDetails_antecedentCause4'', '''')\n  ) AS \"Cause E: Label\",\n  COALESCE(\n    base.declaration->''eventDetails_antecedentCause4''->>''value'',\n    ''''::text\n  ) AS \"Cause E: Code\",\n  NULLIF(\n    TRIM(\n      C', NULL);
INSERT INTO SYSTEM_LOB_STREAM VALUES(273, 1, 'OALESCE(base.declaration->''eventDetails_antecedentCauseInterval4''->>''numericValue'', '''') || '' '' ||\n      COALESCE(base.declaration->''eventDetails_antecedentCauseInterval4''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause E: Interval\"\n\nFROM base\nWHERE\n  COALESCE(\n    base.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n    base.declaration->''eventDetails_antecedentCause1''->>''label'',\n    base.declaration->''eventDetails_antecedentCause2''->>''label'',\n    base.declaration->''eventDetails_antecedentCause3''->>''label'',\n    base.declaration->''eventDetails_antecedentCause4''->>''label''\n  ) IS NOT NULL\nORDER BY \"CertificateKey\";"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}', NULL);    
INSERT INTO SYSTEM_LOB_STREAM VALUES(274, 0, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH declare_base AS (\n  SELECT DISTINCT ON (ea.event_id)\n    ea.event_id,\n    ea.created_at,\n    ea.declaration\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n  ORDER BY ea.event_id, ea.created_at DESC\n),\nregister_base AS (\n  SELECT DISTINCT ON (ea.event_id)\n    ea.event_id,\n    ea.created_at,\n    ea.declaration\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''REGISTER''\n  ORDER BY ea.event_id, ea.created_at DESC\n)\nSELECT\n  d.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n\n  -- Underlying cause comes from REGISTER row\n  r.declaration->>''irisOutput_ucCode'' AS \"Underlying cause: Code\",\n  CASE r.declaration->>''irisOutput_ucCode''\n    WHEN d.declaration->''eventDetails_immediateCauseOfDeath''->>''value''\n      THEN d.declaration->''eventDetails_immediateCauseOfDeath''->>''label''\n    WHEN d.declaration->''eventDetails_antecedentCause1''->>''value''\n      THEN d.declaration->''eventDetails_antecedentCause1''->>''label''\n    WHEN d.declaration->''eventDetails_antecedentCause2''->>''value''\n      THEN d.declaration->''eventDetails_antecedentCause2''->>''label''\n    WHEN d.declaration->''eventDetails_antecedentCause3''->>''value''\n      THEN d.declaration->''eventDetails_antecedentCause3''->>''label''\n    WHEN d.declaration->''eventDetails_antecedentCause4''->>''value''\n      THEN d.declaration->''eventDetails_antecedentCause4''->>''label''\n    ELSE NULL\n  END AS \"Underlying cause: Label\",\n\n  -- Cause A (Immediate) from DECLARE\n  d.declaration->''eventDetails_immediateCauseOfDeath''->>''label'' AS \"Cause A: Label\",\n  d.declaration->''eventDetails_immediateCauseOfDeath''->>''value'' AS \"Cause A: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause A: Interval\",\n\n  -- Cause B\n  d.declaration->''eventDetails_antecedentCause1''->>''label'' AS \"Cause B: Label\",\n  d.declaration->''eventDetails_antecedentCause1''->>''value'' AS \"Cause B: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval1''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval1''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause B: Interval\",\n\n  -- Cause C\n  d.declaration->''eventDetails_antecedentCause2''->>''label'' AS \"Cause C: Label\",\n  d.declaration->''eventDetails_antecedentCause2''->>''value'' AS \"Cause C: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval2''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval2''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause C: Interval\",\n\n  -- Cause D\n  d.declaration->''eventDetails_antecedentCause3''->>''label'' AS \"Cause D: Label\",\n  d.declaration->''eventDetails_antecedentCause3''->>''value'' AS \"Cause D: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval3''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval3''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause D: Interval\",\n\n  -- Cause E\n  d.declaration->''eventDetails_antecedentCause4''->>''label'' AS \"Cause E: Label\",\n  d.declaration->''eventDetails_antecedentCause4''->>''value'' AS \"Cause E: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval4''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval4''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause E: Interval\"\n\nFROM declare_base d\nJOIN register_base r\n  ON r.event_id = d.event_id\nWHERE\n  -- keep only rows where at least one cause label exists\n  COALESCE(\n    d.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n    d.declaration->''eventDetails_antecedentCause1''->>''label'',\n    d.declaratio', NULL);      
INSERT INTO SYSTEM_LOB_STREAM VALUES(274, 1, 'n->''eventDetails_antecedentCause2''->>''label'',\n    d.declaration->''eventDetails_antecedentCause3''->>''label'',\n    d.declaration->''eventDetails_antecedentCause4''->>''label''\n  ) IS NOT NULL\nORDER BY \"CertificateKey\";"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}', NULL);        
INSERT INTO SYSTEM_LOB_STREAM VALUES(275, 0, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH declare_base AS (\n  SELECT DISTINCT ON (ea.event_id)\n    ea.event_id,\n    ea.created_at,\n    ea.declaration\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n  ORDER BY ea.event_id, ea.created_at DESC\n),\nregister_base AS (\n  SELECT DISTINCT ON (ea.event_id)\n    ea.event_id,\n    ea.created_at,\n    ea.declaration\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''REGISTER''\n  ORDER BY ea.event_id, ea.created_at DESC\n)\nSELECT\n  d.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n\n  r.declaration->>''irisOutput_ucCode'' AS \"Underlying cause: Code\",\n\n  COALESCE(\n    -- Prefer label from the supplied causes if the code matches one of them\n    CASE regexp_replace(r.declaration->>''irisOutput_ucCode'', ''\\.'', '''', ''g'')\n      WHEN regexp_replace(d.declaration->''eventDetails_immediateCauseOfDeath''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_immediateCauseOfDeath''->>''label''\n      WHEN regexp_replace(d.declaration->''eventDetails_antecedentCause1''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_antecedentCause1''->>''label''\n      WHEN regexp_replace(d.declaration->''eventDetails_antecedentCause2''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_antecedentCause2''->>''label''\n      WHEN regexp_replace(d.declaration->''eventDetails_antecedentCause3''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_antecedentCause3''->>''label''\n      WHEN regexp_replace(d.declaration->''eventDetails_antecedentCause4''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_antecedentCause4''->>''label''\n      ELSE NULL\n    END,\n\n    -- Fallback to ICD10 reference table\n    icd.label\n  ) AS \"Underlying cause: Label\",\n\n  -- Cause A (Immediate)\n  d.declaration->''eventDetails_immediateCauseOfDeath''->>''label'' AS \"Cause A: Label\",\n  d.declaration->''eventDetails_immediateCauseOfDeath''->>''value'' AS \"Cause A: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause A: Interval\",\n\n  -- Cause B\n  d.declaration->''eventDetails_antecedentCause1''->>''label'' AS \"Cause B: Label\",\n  d.declaration->''eventDetails_antecedentCause1''->>''value'' AS \"Cause B: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval1''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval1''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause B: Interval\",\n\n  -- Cause C\n  d.declaration->''eventDetails_antecedentCause2''->>''label'' AS \"Cause C: Label\",\n  d.declaration->''eventDetails_antecedentCause2''->>''value'' AS \"Cause C: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval2''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval2''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause C: Interval\",\n\n  -- Cause D\n  d.declaration->''eventDetails_antecedentCause3''->>''label'' AS \"Cause D: Label\",\n  d.declaration->''eventDetails_antecedentCause3''->>''value'' AS \"Cause D: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval3''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval3''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause D: Interval\",\n\n  -- Cause E\n  d.declaration->''eventDetails_antecedentCause4''->>''label'' AS \"Cause E: Label\",\n  d.declaration->''eventDetails_antecedentCause4''->>''value'' AS \"Cause E: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval4''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval4''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause ', NULL);          
