(X'bfe1dad17a00da534fd7c6634bc49e15d2b63b5d8788de5e4f462a75ef1f433c', 12, '{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT DISTINCT ON (d.event_id)\n  d.\"CertificateKey\",\n  ''''::text AS \"LastChange\",\n  to_char(d.\"DateBirth\"::timestamp, ''DD/MM/YYYY'') AS \"DateBirth\",\n  to_char(d.\"DateDeath\"::timestamp, ''DD/MM/YYYY'') AS \"DateDeath\",\n  CASE\n    WHEN d.\"DateBirth\" IS NOT NULL AND d.\"DateDeath\" IS NOT NULL\n      THEN EXTRACT(YEAR FROM age(d.\"DateDeath\", d.\"DateBirth\"))::int || '' Years''\n    WHEN d.\"DeclaredAge\" IS NOT NULL\n      THEN d.\"DeclaredAge\"::text || '' Years''\n    ELSE NULL\n  END AS \"Age\",\n  d.\"Sex\",\n  d.\"Comments\"\nFROM (\n  SELECT\n    ea.event_id,\n    ea.created_at,\n\tea.created_at_location AS location_id,\n    ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    NULLIF(ea.declaration->>''deceased_dob'','''')::date AS \"DateBirth\",\n    NULLIF(ea.declaration->>''deceased_eventDate'','''')::date AS \"DateDeath\",\n    NULLIF(ea.declaration->''deceased_age''->>''age'','''')::int AS \"DeclaredAge\",\n    CASE COALESCE(NULLIF(ea.declaration->>''deceased_gender'',''''),''9'')\n      WHEN ''1'' THEN ''Male''\n      WHEN ''2'' THEN ''Female''\n      WHEN ''8'' THEN ''Other''\n      ELSE ''Unknown''\n    END AS \"Sex\",\n    NULLIF(ea.annotation->>''review_comment'', '''') AS \"Comments\"\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND (\n      ea.declaration->>''irisOutput_ucCode'' IS NULL\n      OR ea.declaration->>''irisOutput_ucCode'' = ''None''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions r\n      WHERE r.event_id = ea.event_id\n        AND r.action_type = ''REGISTER''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions a\n      WHERE a.event_id = ea.event_id\n        AND a.action_type = ''ARCHIVE''\n    )\n) d\nORDER BY d.event_id, d.created_at DESC;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}');    
INSERT INTO SYSTEM_LOB_STREAM VALUES(300, 0, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH latest_declare AS (\n  SELECT *\n  FROM (\n    SELECT\n      ea.*,\n\t  ea.created_at_location AS location_id,\n      ROW_NUMBER() OVER (\n        PARTITION BY ea.event_id\n        ORDER BY ea.created_at DESC, ea.id DESC\n      ) AS rn\n    FROM analytics.event_actions ea\n    WHERE ea.action_type = ''DECLARE''\n  ) x\n  WHERE x.rn = 1\n),\nbase AS (\n  SELECT ld.*\n  FROM latest_declare ld\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM analytics.event_actions r\n    WHERE r.event_id = ld.event_id\n      AND r.registration_number IS NOT NULL\n      AND NULLIF(r.declaration->>''irisOutput_ucCode'', '''') IS NOT NULL\n  )\n  AND NOT EXISTS (\n    SELECT 1\n    FROM analytics.event_actions a\n    WHERE a.event_id = ld.event_id\n      AND a.action_type = ''ARCHIVE''\n  )\n)\n\nSELECT\n  t.\"CertificateKey\",\n  t.\"LineNb\",\n  t.\"TextLine\",\n  t.\"CodeLine\",\n  t.\"IntervalLine\"\nFROM (\n  -- causeOfDeathA\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    0 AS \"LineNb\",\n    NULLIF(\n      concat_ws(\n        ''; '',\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_one''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_one_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_one''->>''label'', '''')\n        END,\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_two''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_two_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_two''->>''label'', '''')\n        END,\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_three''->>''value'' = ''OTHER''\n            THEN NULLIF(