INSERT INTO SYSTEM_LOB_STREAM VALUES(302, 0, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH latest_declare AS (\n  SELECT *\n  FROM (\n    SELECT\n      ea.*,\n      ea.created_at_location AS location_id,\n      l.name AS location_name,\n      ROW_NUMBER() OVER (\n        PARTITION BY ea.event_id\n        ORDER BY ea.created_at DESC, ea.id DESC\n      ) AS rn\n    FROM analytics.event_actions ea\n    LEFT JOIN analytics.locations l\n      ON ea.created_at_location = l.id\n    WHERE ea.action_type = ''DECLARE''\n  ) x\n  WHERE x.rn = 1\n),\nbase AS (\n  SELECT ld.*\n  FROM latest_declare ld\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM analytics.event_actions r\n    WHERE r.event_id = ld.event_id\n      AND r.registration_number IS NOT NULL\n      AND NULLIF(r.declaration->>''irisOutput_ucCode'', '''') IS NOT NULL\n  )\n  AND NOT EXISTS (\n    SELECT 1\n    FROM analytics.event_actions a\n    WHERE a.event_id = ld.event_id\n      AND a.action_type = ''ARCHIVE''\n  )\n)\n\nSELECT\n  t.location_id,\n  t.location_name,\n  t.\"CertificateKey\",\n  t.\"LineNb\",\n  t.\"TextLine\",\n  t.\"CodeLine\",\n  t.\"IntervalLine\"\nFROM (\n  -- causeOfDeathA\n  SELECT\n    base.location_id,\n    base.location_name,\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    0 AS \"LineNb\",\n    NULLIF(\n      concat_ws(\n        ''; '',\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_one''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_one_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_one''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_two''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_two_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_two''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_three''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_three_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_three''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_four''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_four_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_four''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_five''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_five_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_five''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_six''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_six_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_six''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_seven''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_seven_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_seven''->>''label'', '''') END,\n        CASE WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_eight''->>''value'' = ''OTHER''\n          THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_eight_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_eight''->>''label'', '''') END\n      ),\n      ''''\n    ) AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      TRIM(\n