INSERT INTO "PUBLIC"."QUERY" VALUES
(X'265c4cfbab90a832de63bd4ca0293ff3c27b28547b08cb308ec752e796853d25', 38, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE administrative_area_path AS (\n    -- roots\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aa.name::text AS administrative_area_path,\n        1 AS level\n    FROM app.administrative_areas aa\n    WHERE aa.parent_id IS NULL\n\n    UNION ALL\n\n    -- descendants\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aap.administrative_area_path || '','' || aa.name,\n        aap.level + 1\n    FROM app.administrative_areas aa\n    JOIN administrative_area_path aap\n        ON aa.parent_id = aap.id\n),\n\npivot AS (\n    SELECT\n        id,\n\n        split_part(administrative_area_path, '','', 1)  AS level_1_name,\n        split_part(administrative_area_path, '','', 2)  AS level_2_name,\n        split_part(administrative_area_path, '','', 3)  AS level_3_name,\n        split_part(administrative_area_path, '','', 4)  AS level_4_name,\n        split_part(administrative_area_path, '','', 5)  AS level_5_name,\n        split_part(administrative_area_path, '','', 6)  AS level_6_name,\n        split_part(administrative_area_path, '','', 7)  AS level_7_name,\n        split_part(administrative_area_path, '','', 8)  AS level_8_name,\n        split_part(administrative_area_path, '','', 9)  AS level_9_name,\n        split_part(administrative_area_path, '','', 10) AS level_10_name\n\n    FROM administrative_area_path\n)\n\nSELECT\n\tl.id::text AS id,\n    l.name,\n    l.created_at,\n    l.updated_at,\n    l.deleted_at,\n    l.location_type,\n    l.valid_until,\n    l.administrative_area_id,\n    l.external_id,\n\n    aa.name AS administrative_area_name,\n\n    aap.administrative_area_path,\n    aap.level AS administrative_area_level,\n\n    -- include location itself in the final full path\n    CASE\n        WHEN aap.administrative_area_path IS NOT NULL\n            THEN aap.administrative_area_path || '','' || l.name\n        ELSE l.name\n    END AS full_path,\n\n    p.level_1_name,\n    p.level_2_name,\n    p.level_3_name,\n    p.level_4_name,\n    p.level_5_name,\n    p.level_6_name,\n    p.level_7_name,\n    p.level_8_name,\n    p.level_9_name,\n    p.level_10_name\n\nFROM app.locations l\n\nLEFT JOIN app.administrative_areas aa\n    ON aa.id = l.administrative_area_id\n\nLEFT JOIN administrative_area_path aap\n    ON aap.id = aa.id\n\nLEFT JOIN pivot p\n    ON p.id = aa.id;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'f2121d91a5a8ac5b0988d8821412bd895960f50d381212890fc8590effbba746', 25, '{"constraints":{"max-results":10000,"max-results-bare-rows":2000},"type":"native","middleware":{"js-int-to-string?":true,"ignore-cached-results?":false,"process-viz-settings?":false,"userland-query?":true},"cache-strategy":null,"native":{"template-tags":{},"query":"WITH RECURSIVE administrative_area_path AS (\n    -- roots\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aa.name::text AS administrative_area_path,\n        1 AS level\n    FROM app.administrative_areas aa\n    WHERE aa.parent_id IS NULL\n\n    UNION ALL\n\n    -- descendants\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aap.administrative_area_path || '','' || aa.name,\n        aap.level + 1\n    FROM app.administrative_areas aa\n    JOIN administrative_area_path aap\n        ON aa.parent_id = aap.id\n),\n\npivot AS (\n    SELECT\n        id,\n\n        split_part(administrative_area_path, '','', 1)  AS level_1_name,\n        split_part(administrative_area_path, '','', 2)  AS level_2_name,\n        split_part(administrative_area_path, '','', 3)  AS level_3_name,\n        split_part(administrative_area_path, '','', 4)  AS level_4_name,\n        split_part(administrative_area_path, '','', 5)  AS level_5_name,\n        split_part(administrative_area_path, '','', 6)  AS level_6_name,\n        split_part(administrative_area_path, '','', 7)  AS level_7_name,\n        split_part(administrative_area_path, '','', 8)  AS level_8_name,\n        split_part(administrative_area_path, '','', 9)  AS level_9_name,\n        split_part(administrative_area_path, '','', 10) AS level_10_name\n\n    FROM administrative_area_path\n)\n\nSELECT\n\tl.id::text AS id,\n    l.name,\n    l.created_at,\n    l.updated_at,\n    l.deleted_at,\n    l.location_type,\n    l.valid_until,\n    l.administrative_area_id,\n    l.external_id,\n\n    aa.name AS administrative_area_name,\n\n    aap.administrative_area_path,\n    aap.level AS administrative_area_level,\n\n    -- include location itself in the final full path\n    CASE\n        WHEN aap.administrative_area_path IS NOT NULL\n            THEN aap.administrative_area_path || '','' || l.name\n        ELSE l.name\n    END AS full_path,\n\n    p.level_1_name,\n    p.level_2_name,\n    p.level_3_name,\n    p.level_4_name,\n    p.level_5_name,\n    p.level_6_name,\n    p.level_7_name,\n    p.level_8_name,\n    p.level_9_name,\n    p.level_10_name\n\nFROM app.locations l\n\nLEFT JOIN app.administrative_areas aa\n    ON aa.id = l.administrative_area_id\n\nLEFT JOIN administrative_area_path aap\n    ON aap.id = aa.id\n\nLEFT JOIN pivot p\n    ON p.id = aa.id;"},"viz-settings":{"table.pivot_column":"created_at","table.cell_column":"valid_until"},"database":2}');      
