(X'7e368cd6aaa3cf0b172a4471a4cf25d14d46981fb909cdadf9394d98e41213ab', 55, U&'{"database":2,"type":"native","native":{"template-tags":{},"query":"-- SELECT\\n--   (\\n--     \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''irisOutput_ucCode'' ] :: text [ ]\\n--   ) :: text AS \\"declaration \2192 irisOutput_ucCode\\",\\n--   (\\n--     \\"analytics\\".\\"event_actions\\".\\"declaration\\" #>> array [ ''eventDetails_causeOfDeathA_symptom_one'',\\n--     ''label'' ] :: text [ ]\\n--   ) :: text AS \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\",\\n--   COUNT(*) AS \\"count\\",\\n--   ROUND(\\n--     100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\n--     2\\n--   ) AS percentage\\n-- FROM\\n--   \\"analytics\\".\\"event_actions\\"\\n-- WHERE\\n--   \\"analytics\\".\\"event_actions\\".\\"action_type\\" = ''REGISTER''\\n-- GROUP BY\\n--   \\"declaration \2192 irisOutput_ucCode\\",\\n--   \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\"\\n-- ORDER BY\\n--   \\"count\\" DESC,\\n--   \\"declaration \2192 irisOutput_ucCode\\" ASC,\\n--   \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\" ASC\\n-- LIMIT\\n--   10\\n\\n\\nWITH causes AS (\\n  SELECT\\n    (\\n      declaration #>> ARRAY[''irisOutput_ucCode'']\\n    ) AS uc_code,\\n    (\\n      declaration #>> ARRAY[\\n        ''eventDetails_causeOfDeathA_symptom_one'',\\n        ''label''\\n      ]\\n    ) AS symptom,\\n    COUNT(*) AS count,\\n    ROUND(\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\n      2\\n    ) AS percentage\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n  GROUP BY 1, 2\\n),\\n\\ntop10 AS (\\n  SELECT *\\n  FROM causes\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\n  LIMIT 10\\n)\\n\\nSELECT\\n  uc_code AS \\"declaration \2192 irisOutput_ucCode\\",\\n  symptom AS \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\",\\n  count,\\n  percentage\\nFROM top10\\n\\nUNION ALL\\n\\nSELECT\\n  ''Total (Top 10)'',\\n  '''',\\n  SUM(count),\\n  ROUND(SUM(percentage), 2)\\nFROM top10;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
(X'245e8e7a07314e0d90e335e9eb4f7eb33c263603444327e573d7bf03f057bb4b', 29, U&'{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH causes AS (\\n  SELECT\\n    (\\n      declaration #>> ARRAY[''irisOutput_ucCode'']\\n    ) AS uc_code,\\n    (\\n      declaration #>> ARRAY[\\n        ''eventDetails_causeOfDeathA_symptom_one'',\\n        ''label''\\n      ]\\n    ) AS symptom,\\n    COUNT(*) AS count,\\n    ROUND(\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\n      2\\n    ) AS percentage\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n  GROUP BY 1, 2\\n),\\n\\ntop10 AS (\\n  SELECT *\\n  FROM causes\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\n  LIMIT 10\\n),\\n\\nranked AS (\\n  SELECT\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\n    uc_code,\\n    symptom,\\n    count,\\n    percentage\\n  FROM top10\\n)\\n\\nSELECT\\n  rank AS \\"RANK\\",\\n  uc_code AS \\"declaration \2192 irisOutput_ucCode\\",\\n  symptom AS \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\",\\n  count,\\n  percentage\\nFROM ranked\\n\\nUNION ALL\\n\\nSELECT\\n  ''Total (Top 10)'',\\n  '''',\\n  '''',\\n  SUM(count),\\n  ROUND(SUM(percentage), 2)\\nFROM ranked;"},"middleware":{"js-int-to-string?":true,"userland-query?":true,"add-default-userland-constraints?":true}}'),
