INSERT INTO "PUBLIC"."REPORT_CARD" VALUES
(51, TIMESTAMP WITH TIME ZONE '2025-08-19 09:05:05.541818+03', TIMESTAMP WITH TIME ZONE '2025-09-04 13:28:10.220119+03', 'Registrations by State', NULL, 'map', '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE r AS (\n  -- base: count by lowest location\n  SELECT\n    ea.created_at_location AS location_id,\n    COUNT(*)              AS count,\n    l.name,\n    l.parent_id,\n    0 AS level\n  FROM app.event_actions ea\n  JOIN app.locations l ON ea.created_at_location = l.id\n  WHERE ea.action_type = ''REGISTER''\n  GROUP BY ea.created_at_location, l.name, l.parent_id\n\n  UNION ALL\n\n  -- climb up the hierarchy\n  SELECT\n    r.location_id,\n    r.count,\n    p.name,\n    p.parent_id,\n    r.level + 1\n  FROM r\n  JOIN app.locations p ON r.parent_id = p.id\n)\n\nSELECT\n  location_id,\n  MAX(CASE WHEN level = 0 THEN name END) AS level_0,\n  MAX(CASE WHEN level = 1 THEN name END) AS level_1,\n  MAX(CASE WHEN level = 2 THEN name END) AS level_2,\n  MAX(CASE WHEN level = 3 THEN name END) AS level_3,\n  MAX(count) AS count\nFROM r\nGROUP BY location_id\nORDER BY count DESC;"}}', '{"map.region":"cdc1d5eb-c7f8-8b01-b296-eda34d06b6da","map.dimension":"level_2","map.metric":"count"}', 1, 2, NULL, 'native', TRUE, 5, NULL, NULL, FALSE, NULL, NULL, '[{"database_type":"uuid","semantic_type":null,"lib/deduplicated-name":"location_id","lib/original-name":"location_id","name":"location_id","lib/source":"source/native","source":"native","field_ref":["field","location_id",{"base-type":"type/UUID"}],"effective_type":"type/UUID","display_name":"location_id","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":36.0}}},"base_type":"type/UUID"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"level_0","lib/original-name":"level_0","name":"level_0","lib/source":"source/native","source":"native","field_ref":["field","level_0",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"level_0","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":22.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"level_1","lib/original-name":"level_1","name":"level_1","lib/source":"source/native","source":"native","field_ref":["field","level_1",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"level_1","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":6.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"level_2","lib/original-name":"level_2","name":"level_2","lib/source":"source/native","source":"native","field_ref":["field","level_2",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"level_2","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":7.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"level_3","lib/original-name":"level_3","name":"level_3","lib/source":"source/native","source":"native","field_ref":["field","level_3",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"level_3","fingerprint":{"global":{"distinct-count":1,"nil%":1.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":0.0}}},"base_type":"type/Text"},{"database_type":"int8","semantic_type":"type/Quantity","lib/deduplicated-name":"count","lib/original-name":"count","name":"count","lib/source":"source/native","source":"native","field_ref":["field","count",{"base-type":"type/BigInteger"}],"eff