(69, TIMESTAMP WITH TIME ZONE '2025-09-04 13:24:33.192354+03', TIMESTAMP WITH TIME ZONE '2025-09-04 13:28:10.220119+03', 'Number of Registrations by event type', NULL, 'scalar', '{"database":2,"type":"query","query":{"breakout":[["field","event_type",{"base-type":"type/Text"}]],"aggregation":[["count"]],"source-table":"card__66"}}', '{"table.pivot_column":"action_type","table.cell_column":"content","scalar.field":"count"}', 1, 2, NULL, 'query', TRUE, 5, NULL, NULL, FALSE, NULL, NULL, '[{"database_type":"text","semantic_type":"type/Category","lib/deduplicated-name":"event_type","lib/original-name":"event_type","lib/breakout?":true,"name":"event_type","lib/card-id":66,"lib/source":"source/previous-stage","lib/source-column-alias":"event_type","lib/model-display-name":"event_type","source":"breakout","field_ref":["field","event_type",{"base-type":"type/Text"}],"effective_type":"type/Text","lib/desired-column-alias":"event_type","display_name":"event_type","fingerprint":{"global":{"distinct-count":2,"nil%":0},"type":{"type/Text":{"percent-json":0,"percent-url":0,"percent-email":0,"percent-state":0,"average-length":17.333333333333332}}},"base_type":"type/Text"},{"database_type":"int8","semantic_type":"type/Quantity","lib/deduplicated-name":"count","lib/original-name":"count","name":"count","lib/source":"source/aggregations","lib/source-column-alias":"count","source":"aggregation","field_ref":["aggregation",0],"effective_type":"type/BigInteger","lib/desired-column-alias":"count","display_name":"Count","fingerprint":{"global":{"distinct-count":2,"nil%":0},"type":{"type/Number":{"min":1,"q1":1,"q3":2,"max":2,"sd":0.7071067811865476,"avg":1.5}}},"base_type":"type/BigInteger"}]', NULL, 'JpBLc-JwfZv069f4HbW9b', '[]', '[]', TRUE, 'v0.56.4 (aeaacd0)', 'question', NULL, NULL, TIMESTAMP WITH TIME ZONE '2025-09-04 13:26:39.235462+03', 4, FALSE, NULL, 66, NULL, 22),
(71, TIMESTAMP WITH TIME ZONE '2025-09-04 13:31:14.91944+03', TIMESTAMP WITH TIME ZONE '2026-06-01 15:01:22.728774+02', 'Locations', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE administrative_area_path AS (\n    -- roots\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aa.name::text AS administrative_area_path,\n        1 AS level\n    FROM app.administrative_areas aa\n    WHERE aa.parent_id IS NULL\n\n    UNION ALL\n\n    -- descendants\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aap.administrative_area_path || '','' || aa.name,\n        aap.level + 1\n    FROM app.administrative_areas aa\n    JOIN administrative_area_path aap\n        ON aa.parent_id = aap.id\n),\n\npivot AS (\n    SELECT\n        id,\n\n        split_part(administrative_area_path, '','', 1)  AS level_1_name,\n        split_part(administrative_area_path, '','', 2)  AS level_2_name,\n        split_part(administrative_area_path, '','', 3)  AS level_3_name,\n        split_part(administrative_area_path, '','', 4)  AS level_4_name,\n        split_part(administrative_area_path, '','', 5)  AS level_5_name,\n        split_part(administrative_area_path, '','', 6)  AS level_6_name,\n        split_part(administrative_area_path, '','', 7)  AS level_7_name,\n        split_part(administrative_area_path, '','', 8)  AS level_8_name,\n        split_part(administrative_area_path, '','', 9)  AS level_9_name,\n        split_part(administrative_area_path, '','', 10) AS level_10_name\n\n    FROM administrative_area_path\n)\n\nSELECT\n\tl.id::text AS id,\n    l.name,\n    l.created_at,\n    l.updated_at,\n    l.deleted_at,\n    l.location_type,\n    l.valid_until,\n    l.administrative_area_id,\n    l.external_id,\n\n    aa.name AS administrative_area_name,\n\n    aap.administrative_area_path,\n    aap.level AS administrative_area_level,\n\n    -- include location itself in the final full path\n    CASE\n        WHEN aap.administrative_area_path IS NOT NULL\n            THEN aap.administrative_area_path || '','' || l.name\n        ELSE l.name\n    END AS full_path,\n\n    p.level_1_name,\n    p.level_2_name,\n    p.level_3_name,\n    p.level_4_name,\n    p.level_5_name,\n    p.level_6_name,\n    p.level_7_name,\n    p.level_8_name,\n    p.level_9_name,\n    p.level_10_name\n\nFROM app.locations l\n\nLEFT JOIN app.administrative_areas aa\n    ON aa.id = l.administrative_area_id\n\nLEFT JOIN administrative_area_path aap\n    ON aap.id = aa.id\n\nLEFT JOIN pivot p\n    ON p.id = aa.id;"}}', '{"table.pivot_column":"created_at","table.cell_column":"valid_until"}', 1, 2, NULL, 'native', FALSE, NULL, NULL, NULL, FALSE, NULL, NULL, SYSTEM_COMBINE_CLOB(315), 10, '5SV2UPY4AnfEAcrc6ZLFv', '[]', '[]', TRUE, 'v0.56.4 (aeaacd0)', 'model', NULL, TIMESTAMP WITH TIME ZONE '2026-06-01 15:01:22.725558+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:29:56.224288+02', 81, FALSE, NULL, NULL, NULL, 22);          
