INSERT INTO "PUBLIC"."REPORT_CARD" VALUES
(124, TIMESTAMP WITH TIME ZONE '2025-09-12 10:07:18.436943+03', TIMESTAMP WITH TIME ZONE '2025-10-10 13:59:59.326827+03', 'Births completeness rates', 'Completeness rates per location per year, based on country provided population and crude birth rate statistics', 'table', '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE levels AS (\n    -- root = 1, children increment\n    SELECT id, parent_id, 1 AS level\n    FROM analytics.locations\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT l.id, l.parent_id, lv.level + 1\n    FROM analytics.locations l\n    JOIN levels lv ON l.parent_id = lv.id\n),\n-- ancestor/descendant closure: every node is ancestor of itself and all its descendants\nclosure AS (\n    SELECT id AS ancestor_id, id AS descendant_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT c.ancestor_id, l.id AS descendant_id\n    FROM closure c\n    JOIN analytics.locations l ON l.parent_id = c.descendant_id\n),\n-- counts at leaf/origin locations by year\ncounts AS (\n\tSELECT ea.created_at_location AS location_id,\n\t       EXTRACT(YEAR FROM ea.created_at)::int AS year,\n\t       COUNT(*) AS cnt\n\tFROM analytics.event_actions ea\n\tWHERE ea.action_type = ''REGISTER''\n\t  AND ea.event_type  = ''birth''\n\t  AND ea.created_at IS NOT NULL\n\t  AND ea.created_at_location IS NOT NULL\n\t  AND (ea.declaration->>''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\n\tGROUP BY ea.created_at_location, year\n),\n-- roll up descendant counts to each ancestor (this is the named query)\nbirth_registrations_per_location AS (\n    SELECT c.ancestor_id AS location_id,\n           cnt.year,\n           SUM(cnt.cnt) AS register_count\n    FROM closure c\n    JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY c.ancestor_id, cnt.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count,\n\t(register_count / (s.total_population / 1000 * s.crude_birth_rate) * 100) as completeness_rate,\n    lv.level,\n    ll.name AS level_name\nFROM analytics.locations l\nJOIN analytics.location_statistics s\n  ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br\n  ON br.location_id = l.id AND br.year = s.year\nLEFT JOIN levels lv\n  ON lv.id = l.id\nLEFT JOIN analytics.location_levels ll\n  ON ll.level = lv.level\nORDER BY s.year DESC, register_count DESC;"}}', '{"graph.x_axis.scale":"ordinal","graph.dimensions":["name"],"graph.metrics":[],"table.pivot_column":"crude_birth_rate","table.cell_column":"year"}', 1, 2, NULL, 'native', FALSE, 9, NULL, NULL, FALSE, NULL, NULL, SYSTEM_COMBINE_CLOB(335), 1, 'dTJlMmm0y9G98CTByr9-S', '[]', '[]', TRUE, 'v0.56.4 (aeaacd0)', 'model', NULL, TIMESTAMP WITH TIME ZONE '2025-10-10 13:59:59.324939+03', TIMESTAMP WITH TIME ZONE '2025-12-09 15:32:05.150451+00', 90, FALSE, NULL, NULL, NULL, 22),
(125, TIMESTAMP WITH TIME ZONE '2025-09-12 10:47:16.128521+03', TIMESTAMP WITH TIME ZONE '2025-09-12 11:03:33.835271+03', 'Births completeness rates by state', 'Completeness rates per location per year, based on country provided population and crude birth rate statistics', 'bar', '{"database":2,"type":"query","query":{"joins":[{"fields":"all","strategy":"left-join","alias":"Admin Locations - name","condition":["=",["field","name",{"base-type":"type/Text"}],["field",276,{"base-type":"type/Text","join-alias":"Admin Locations - name"}]],"source-table":"card__92"}],"source-table":"card__124","filter":["=",["field","level",{"base-type":"type/Integer","join-alias":"Admin Locations - name"}],1]}}', '{"graph.y_axis.title_text":"Completness Rates","graph.show_values":false,"graph.x_axis.labels_enabled":false,"graph.y_axis.labels_enabled":true,"graph.y_axis.scale":"linear","graph.metrics":["completeness_rate"],"graph.y_axis.auto_range":false,"graph.x_axis.scale":"ordinal","graph.dimensions":["name"]}', 1, 2, NULL, 'query', FALSE, 9, NULL, NULL, FALSE, NULL, NULL, SYSTEM_COMBINE_CLOB(336), NULL, 'SlnPXcddawaoWsDK7_MIV', '[]', '[]', TRUE, 'v0.56.4 (aeaacd0)', 'question', NULL, TIMESTAMP WITH TIME ZONE '2025-09-12 11:03:33.833253+03', TIMESTAMP WITH TIME ZONE '2025-09-12 11:20:16.820095+03', 27, FALSE, NULL, 124, NULL, 22);             
