(129, TIMESTAMP WITH TIME ZONE '2025-09-15 09:39:46.444299+03', TIMESTAMP WITH TIME ZONE '2025-09-15 10:24:01.329652+03', 'Description block', NULL, 'scalar', '{"database":2,"type":"native","native":{"template-tags":{"my_param":{"type":"text","name":"my_param","id":"4effb4b1-3400-40fd-b19d-9dc6f2fb9224","display-name":"My Param","default":"Test"}},"query":"SELECT {{my_param}} AS title"}}', '{}', 1, 2, NULL, 'native', TRUE, 8, NULL, NULL, FALSE, NULL, NULL, '[{"database_type":"varchar","semantic_type":"type/Title","lib/deduplicated-name":"title","lib/original-name":"title","name":"title","lib/source":"source/native","source":"native","field_ref":["field","title",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"title","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":32.0}}},"base_type":"type/Text"}]', NULL, 'g8EfOb6-2lEVg93LPDX6q', '[{"id":"4effb4b1-3400-40fd-b19d-9dc6f2fb9224","type":"string/=","target":["variable",["template-tag","my_param"]],"name":"My Param","slug":"my_param","default":"Test","isMultiSelect":false}]', '[]', TRUE, 'v0.56.4 (aeaacd0)', 'question', NULL, TIMESTAMP WITH TIME ZONE '2025-09-15 09:44:16.699489+03', TIMESTAMP WITH TIME ZONE '2025-09-15 10:12:35.843653+03', 26, TRUE, NULL, NULL, 11, 22),
(156, TIMESTAMP WITH TIME ZONE '2025-10-16 09:28:43.241794+03', TIMESTAMP WITH TIME ZONE '2025-10-17 14:27:54.392077+03', 'Completeness rate', NULL, 'gauge', '{"database":2,"type":"native","native":{"template-tags":{"year":{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"number","name":"year","display-name":"Year"}},"query":"WITH top_level_locations AS (\n  SELECT name\n  FROM analytics.locations\n  WHERE parent_id IS NULL\n),\npopulation_sum AS (\n  SELECT \n    SUM(total_population) AS total_population\n  FROM \n    analytics.location_statistics s\n  JOIN \n    top_level_locations l ON s.name = l.name\n  WHERE \n    s.year = [[{{year}}]]\n),\nbirth_rate AS (\n  SELECT \n    AVG(crude_birth_rate) AS country_birth_rate\n  FROM \n    analytics.location_statistics\n  WHERE \n    year = [[{{year}}]]\n),\nregistered_births AS (\n  SELECT \n    COUNT(*) AS registered_count\n  FROM \n    analytics.event_actions\n  WHERE \n    action_type = ''REGISTER''\n    AND event_type = ''birth''\n    AND (created_at::date - (declaration->>''child_dob'')::date) < 365\n)\nSELECT \n  r.registered_count / (p.total_population / 1000 * b.country_birth_rate) * 100 AS registered_birth_percentage\nFROM \n  registered_births r,\n  birth_rate b,\n  population_sum p;"}}', '{"gauge.segments":[{"min":0,"max":25,"color":"hsla(358, 71%, 62%, 1)","label":""},{"min":25,"max":75,"color":"#F9CF48","label":""},{"min":75,"max":100,"color":"#84BB4C","label":""}],"column_settings":{"[\"name\",\"registered_birth_percentage\"]":{"suffix":"%"}}}', 1, 2, NULL, 'native', FALSE, 8, NULL, NULL, FALSE, NULL, NULL, '[{"database_type":"numeric","semantic_type":"type/Share","lib/deduplicated-name":"registered_birth_percentage","lib/original-name":"registered_birth_percentage","name":"registered_birth_percentage","lib/source":"source/native","source":"native","field_ref":["field","registered_birth_percentage",{"base-type":"type/Decimal"}],"effective_type":"type/Decimal","display_name":"registered_birth_percentage","fingerprint":{"global":{"distinct-count":1,"nil%":1.0},"type":{"type/Number":{"min":null,"q1":null,"q3":null,"max":null,"sd":null,"avg":null}}},"base_type":"type/Decimal"}]', NULL, 'bU7KUnYAe90s6XK4Uyw88', '[{"id":"be1ae479-6da3-4c17-b7fe-e412a701c0b7","type":"number/=","target":["variable",["template-tag","year"]],"name":"Year","slug":"year","isMultiSelect":false}]', '[]', TRUE, 'v0.56.4 (aeaacd0)', 'question', NULL, TIMESTAMP WITH TIME ZONE '2025-10-17 14:27:54.389921+03', TIMESTAMP WITH TIME ZONE '2025-12-09 15:31:37.570798+00', 29, FALSE, NULL, NULL, 12, 22),
