INSERT INTO SYSTEM_LOB_STREAM VALUES(341, 0, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH latest_declare AS (\n  SELECT *\n  FROM (\n    SELECT\n      ea.*,\n      ROW_NUMBER() OVER (\n        PARTITION BY ea.event_id\n        ORDER BY ea.created_at DESC, ea.id DESC\n      ) AS rn\n    FROM analytics.event_actions ea\n    WHERE ea.action_type = ''DECLARE''\n  ) x\n  WHERE x.rn = 1\n),\nbase AS (\n  SELECT ld.*\n  FROM latest_declare ld\n  WHERE NOT EXISTS (\n    SELECT 1\n    FROM analytics.event_actions r\n    WHERE r.event_id = ld.event_id\n      AND r.registration_number IS NOT NULL\n      AND NULLIF(r.declaration->>''irisOutput_ucCode'', '''') IS NOT NULL\n  )\n  AND NOT EXISTS (\n    SELECT 1\n    FROM analytics.event_actions a\n    WHERE a.event_id = ld.event_id\n      AND a.action_type = ''ARCHIVE''\n  )\n)\n\nSELECT\n  t.\"CertificateKey\",\n  t.\"LineNb\",\n  t.\"TextLine\",\n  t.\"CodeLine\",\n  t.\"IntervalLine\"\nFROM (\n  -- causeOfDeathA\n  SELECT\n    base.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    0 AS \"LineNb\",\n    NULLIF(\n      concat_ws(\n        ''; '',\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_one''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_one_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_one''->>''label'', '''')\n        END,\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_two''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_two_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_two''->>''label'', '''')\n        END,\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_three''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_three_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_three''->>''label'', '''')\n        END,\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_four''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_four_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_four''->>''label'', '''')\n        END,\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_five''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_five_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_five''->>''label'', '''')\n        END,\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_six''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_six_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_six''->>''label'', '''')\n        END,\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_seven''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_seven_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_seven''->>''label'', '''')\n        END,\n        CASE\n          WHEN base.declaration->''eventDetails_causeOfDeathA_symptom_eight''->>''value'' = ''OTHER''\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathA_symptom_eight_other'', '''')\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathA_symptom_eight''->>''label'', '''')\n        END\n      ),\n      ''''\n    ) AS \"TextLine\",\n    ''''::text AS \"CodeLine\",\n    NULLIF(\n      TRIM(\n        COALESCE(base.declaration->''eventDetails_causeOfDeathA_interval''->>''numericValue'', '''') || '' '' ||\n        COALESCE(base.declaration->''eventDetails_causeOfDeathA_interval''->>''unit'', '''')\n      ),\n      ''''\n    ) AS \"IntervalLine\"\n  FROM base\n\n  UNION ALL\n\n  -- causeOfDeathB\n  SELECT\n    base.declaration->>''deceased_certificateKey'' A', NULL);      
