(161, TIMESTAMP WITH TIME ZONE '2025-12-10 14:12:15.994085+00', TIMESTAMP WITH TIME ZONE '2026-05-19 16:13:47.946135+01', 'IDENT', NULL, 'table', '{"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT DISTINCT ON (d.event_id)\n  d.\"CertificateKey\",\n  ''''::text AS \"LastChange\",\n  to_char(d.\"DateBirth\"::timestamp, ''DD/MM/YYYY'') AS \"DateBirth\",\n  to_char(d.\"DateDeath\"::timestamp, ''DD/MM/YYYY'') AS \"DateDeath\",\n  CASE\n    WHEN d.\"DateBirth\" IS NOT NULL AND d.\"DateDeath\" IS NOT NULL\n      THEN EXTRACT(YEAR FROM age(d.\"DateDeath\", d.\"DateBirth\"))::int || '' Years''\n    WHEN d.\"DeclaredAge\" IS NOT NULL\n      THEN d.\"DeclaredAge\"::text || '' Years''\n    ELSE NULL\n  END AS \"Age\",\n  d.\"Sex\",\n  d.\"Comments\"\nFROM (\n  SELECT\n    ea.event_id,\n    ea.created_at,\n    ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    NULLIF(ea.declaration->>''deceased_dob'','''')::date AS \"DateBirth\",\n    NULLIF(ea.declaration->>''deceased_eventDate'','''')::date AS \"DateDeath\",\n    NULLIF(ea.declaration->''deceased_age''->>''age'','''')::int AS \"DeclaredAge\",\n    CASE COALESCE(NULLIF(ea.declaration->>''deceased_gender'',''''),''9'')\n      WHEN ''1'' THEN ''Male''\n      WHEN ''2'' THEN ''Female''\n      WHEN ''8'' THEN ''Other''\n      ELSE ''Unknown''\n    END AS \"Sex\",\n    NULLIF(ea.annotation->>''review_comment'', '''') AS \"Comments\"\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND (\n      ea.declaration->>''irisOutput_ucCode'' IS NULL\n      OR ea.declaration->>''irisOutput_ucCode'' = ''None''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions r\n      WHERE r.event_id = ea.event_id\n        AND r.action_type = ''REGISTER''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions a\n      WHERE a.event_id = ea.event_id\n        AND a.action_type = ''ARCHIVE''\n    )\n) d\nORDER BY d.event_id, d.created_at DESC;"}}', '{"table.pivot_column":"Deceased DOB","table.cell_column":"Deceased age"}', 1, 2, NULL, 'native', TRUE, 8, NULL, NULL, FALSE, NULL, NULL, '[{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"CertificateKey","lib/original-name":"CertificateKey","name":"CertificateKey","lib/source":"source/native","source":"native","field_ref":["field","CertificateKey",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"CertificateKey","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":8.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"LastChange","lib/original-name":"LastChange","name":"LastChange","lib/source":"source/native","source":"native","field_ref":["field","LastChange",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"LastChange","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":0.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"DateBirth","lib/original-name":"DateBirth","name":"DateBirth","lib/source":"source/native","source":"native","field_ref":["field","DateBirth",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"DateBirth","fingerprint":{"global":{"distinct-count":2,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":10.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"DateDeath","lib/original-name":"DateDeath","name":"DateDeath","lib/source":"source/native","source":"native","field_ref":["field","DateDeath",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"DateDeath","fingerprint":{"global":{"distinct-count":4,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":10.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"Age","lib/original-name":"Age","name":"Age","lib/source":"source/native","source":"native","field_ref":["field","Age",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"Age","fingerprint":{"global":{"distinct-count":1,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":8.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":"type/Category","lib/deduplicated-name":"Sex","lib/original-name":"Sex","name":"Sex","lib/source":"source/native","source":"native","field_ref":["field","Sex",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"Sex","fingerprint":{"global":{"distinct-count":2,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":5.0}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":"type/Comment","lib/deduplicated-name":"Comments","lib/original-name":"Comments","name":"Comments","lib/source":"source/native","source":"native","field_ref":["field","Comments",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"Comments","fingerprint":{"global":{"distinct-count":1,"nil%":1.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":0.0}}},"base_type":"type/Text"}]', NULL, 's4DVZsOciQI_QOiHMbC3f', '[]', '[]', TRUE, 'v0.56.4 (aeaacd0)', 'question', NULL, TIMESTAMP WITH TIME ZONE '2026-05-19 14:51:41.312553+01', TIMESTAMP WITH TIME ZONE '2026-05-19 16:13:24.029075+01', 150, TRUE, NULL, NULL, 14, 22);
INSERT INTO SYSTEM_LOB_STREAM VALUES(342, 0, '{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH declare_base AS (\n  SELECT DISTINCT ON (ea.event_id)\n    ea.event_id,\n    ea.created_at,\n    ea.declaration\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n  ORDER BY ea.event_id, ea.created_at DESC\n),\nregister_base AS (\n  SELECT DISTINCT ON (ea.event_id)\n    ea.event_id,\n    ea.created_at,\n    ea.declaration\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''REGISTER''\n  ORDER BY ea.event_id, ea.created_at DESC\n)\nSELECT\n  d.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n\n  -- Demographics (from DECLARE)\n  to_char(NULLIF(d.declaration->>''deceased_dob'','''')::date, ''MM/DD/YYYY'') AS \"DateBirth\",\n  to_char(NULLIF(d.declaration->>''deceased_eventDate'','''')::date, ''MM/DD/YYYY'') AS \"DateDeath\",\n  EXTRACT(\n    YEAR FROM age(\n      NULLIF(d.declaration->>''deceased_eventDate'','''')::date,\n      NULLIF(d.declaration->>''deceased_dob'','''')::date\n    )\n  )::int || '' Years'' AS \"Age\",\n  CASE d.declaration->>''deceased_gender''\n  WHEN ''1'' THEN ''Male''\n  WHEN ''2'' THEN ''Female''\n  WHEN ''8'' THEN ''Other''\n  WHEN ''9'' THEN ''Unknown''\n  ELSE ''Unknown''\nEND AS \"Sex\",\n\n  -- Underlying cause (from REGISTER)\n  r.declaration->>''irisOutput_ucCode'' AS \"Underlying cause: Code\",\n  COALESCE(\n    CASE regexp_replace(r.declaration->>''irisOutput_ucCode'', ''\\.'', '''', ''g'')\n      WHEN regexp_replace(d.declaration->''eventDetails_immediateCauseOfDeath''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_immediateCauseOfDeath''->>''label''\n      WHEN regexp_replace(d.declaration->''eventDetails_antecedentCause1''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_antecedentCause1''->>''label''\n      WHEN regexp_replace(d.declaration->''eventDetails_antecedentCause2''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_antecedentCause2''->>''label''\n      WHEN regexp_replace(d.declaration->''eventDetails_antecedentCause3''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_antecedentCause3''->>''label''\n      WHEN regexp_replace(d.declaration->''eventDetails_antecedentCause4''->>''value'', ''\\.'', '''', ''g'')\n        THEN d.declaration->''eventDetails_antecedentCause4''->>''label''\n      ELSE NULL\n    END,\n    icd.label\n  ) AS \"Underlying cause: Label\",\n\n  -- Cause A (Immediate)\n  d.declaration->''eventDetails_immediateCauseOfDeath''->>''label'' AS \"Cause A: Label\",\n  d.declaration->''eventDetails_immediateCauseOfDeath''->>''value'' AS \"Cause A: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_immediateCauseOfDeathInterval''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause A: Interval\",\n\n  -- Cause B\n  d.declaration->''eventDetails_antecedentCause1''->>''label'' AS \"Cause B: Label\",\n  d.declaration->''eventDetails_antecedentCause1''->>''value'' AS \"Cause B: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval1''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval1''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause B: Interval\",\n\n  -- Cause C\n  d.declaration->''eventDetails_antecedentCause2''->>''label'' AS \"Cause C: Label\",\n  d.declaration->''eventDetails_antecedentCause2''->>''value'' AS \"Cause C: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval2''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval2''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause C: Interval\",\n\n  -- Cause D\n  d.declaration->''eventDetails_antecedentCause3''->>''label'' AS \"Cause D: Label\",\n  d.declaration->''eventDetails_antecedentCause3''->>''value'' AS \"Cause D: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval3''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_', NULL);               
INSERT INTO SYSTEM_LOB_STREAM VALUES(342, 1, 'antecedentCauseInterval3''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause D: Interval\",\n\n  -- Cause E\n  d.declaration->''eventDetails_antecedentCause4''->>''label'' AS \"Cause E: Label\",\n  d.declaration->''eventDetails_antecedentCause4''->>''value'' AS \"Cause E: Code\",\n  NULLIF(\n    TRIM(\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval4''->>''numericValue'', '''') || '' '' ||\n      COALESCE(d.declaration->''eventDetails_antecedentCauseInterval4''->>''unit'', '''')\n    ),\n    ''''\n  ) AS \"Cause E: Interval\"\n\nFROM declare_base d\nJOIN register_base r\n  ON r.event_id = d.event_id\nLEFT JOIN reference_data.icd10 icd\n  ON regexp_replace(icd.code, ''\\.'', '''', ''g'')\n   = regexp_replace(r.declaration->>''irisOutput_ucCode'', ''\\.'', '''', ''g'')\n\nWHERE\n  COALESCE(\n    d.declaration->''eventDetails_immediateCauseOfDeath''->>''label'',\n    d.declaration->''eventDetails_antecedentCause1''->>''label'',\n    d.declaration->''eventDetails_antecedentCause2''->>''label'',\n    d.declaration->''eventDetails_antecedentCause3''->>''label'',\n    d.declaration->''eventDetails_antecedentCause4''->>''label''\n  ) IS NOT NULL\nORDER BY \"CertificateKey\";"}}', NULL);             
