(177, TIMESTAMP WITH TIME ZONE '2026-06-01 16:15:37.313892+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:12:03.204401+02', U&'Major causes \2014 Female', NULL, 'table', U&'{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH causes AS (\\n  SELECT\\n    (\\n      declaration #>> ARRAY[''irisOutput_ucCode'']\\n    ) AS uc_code,\\n    (\\n      declaration #>> ARRAY[\\n        ''eventDetails_causeOfDeathA_symptom_one'',\\n        ''label''\\n      ]\\n    ) AS symptom,\\n    COUNT(*) AS count,\\n    ROUND(\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\n      2\\n    ) AS percentage\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n  GROUP BY 1, 2\\n),\\n\\ntop10 AS (\\n  SELECT *\\n  FROM causes\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\n  LIMIT 10\\n),\\n\\nranked AS (\\n  SELECT\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\n    uc_code,\\n    symptom,\\n    count,\\n    percentage\\n  FROM top10\\n)\\n\\nSELECT\\n  rank AS \\"RANK\\",\\n  uc_code AS \\"declaration \2192 irisOutput_ucCode\\",\\n  symptom AS \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\",\\n  count,\\n  percentage\\nFROM ranked\\n\\nUNION ALL\\n\\nSELECT\\n  ''Total (Top 10)'',\\n  '''',\\n  '''',\\n  SUM(count),\\n  ROUND(SUM(percentage), 2)\\nFROM ranked;"}}', U&'{"table.column_formatting":[],"table.pivot":false,"table.row_index":false,"table.pivot_column":"declaration \2192 irisOutput_ucCode","table.cell_column":"count","table.column_widths":[130],"column_settings":{"[\\"name\\",\\"declaration \2192 irisOutput_ucCode\\"]":{"column_title":"ICD-10","text_wrapping":false},"[\\"name\\",\\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\"]":{"column_title":"DISEASE/CONDITION"},"[\\"name\\",\\"count\\"]":{"column_title":"NO. OF DEATH"},"[\\"name\\",\\"percentage\\"]":{"column_title":"%"}}}', 1, 2, 14, 'native', FALSE, 8, NULL, NULL, FALSE, NULL, NULL, U&'[{"database_t