(184, TIMESTAMP WITH TIME ZONE '2026-06-02 16:40:27.284468+02', TIMESTAMP WITH TIME ZONE '2026-06-02 16:44:10.479626+02', 'Top 10 causes of death -- test', NULL, 'table', U&'{"database":2,"type":"native","native":{"template-tags":{},"query":"WITH causes AS (\\n  SELECT\\n    declaration #>> ARRAY[''irisOutput_ucCode''] AS uc_code,\\n    declaration #>> ARRAY[\\n      ''eventDetails_causeOfDeathA_symptom_one'',\\n      ''label''\\n    ] AS symptom,\\n    COUNT(*) AS count,\\n    ROUND(\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\n      2\\n    ) AS percentage\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n  GROUP BY 1, 2\\n),\\n\\ntop10 AS (\\n  SELECT *\\n  FROM causes\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\n  LIMIT 10\\n),\\n\\nranked AS (\\n  SELECT\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\n    uc_code,\\n    symptom,\\n    count,\\n    percentage\\n  FROM top10\\n)\\n\\nSELECT\\n  rank AS \\"RANK\\",\\n  uc_code AS \\"declaration \2192 irisOutput_ucCode\\",\\n  symptom AS \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\",\\n  count,\\n  percentage\\nFROM ranked;"}}', '{"table.pivot_column":"count","table.cell_column":"percentage"}', 1, 2, NULL, 'native', TRUE, 8, NULL, NULL, FALSE, NULL, NULL, U&'[{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"RANK","lib/original-name":"RANK","name":"RANK","lib/source":"source/native","source":"native","field_ref":["field","RANK",{"base-type":"type/Text"}],"effective_type":"type/Text","display_name":"RANK","fingerprint":{"global":{"distinct-count":10,"nil%":0.0},"type":{"type/Text":{"percent-json":0.0,"percent-url":0.0,"percent-email":0.0,"percent-state":0.0,"average-length":2.1}}},"base_type":"type/Text"},{"database_type":"text","semantic_type":null,"lib/deduplicated-name":"declaration \2192 irisOutput_ucCode","lib/original-name":"declaration \2192 irisOutput_ucCode","name":"declaration \2192 ir