(32, 'All Registrations', 'All Registrations {"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT * FROM analytics.event_actions WHERE action_type = ''REGISTER''"}}', 'dataset', '{"name":"All Registrations","description":null,"collection_name":"OpenCRVS Core Dashboards"}', '{"description":null,"archived":true,"display_type":"table","collection_position":1,"database_id":2,"collection_id":5,"official_collection":null,"name":"All Registrations","collection_name":"OpenCRVS Core Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2025-09-04T13:28:10.220119+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"SELECT * FROM analytics.event_actions WHERE action_type = ''REGISTER''\"}}","last_editor_id":1,"collection_location":"/","id":66,"last_edited_at":"2025-09-04T13:17:56.997039+03:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-09-04T13:17:56.920277+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TRUE, TIMESTAMP WITH TIME ZONE '2025-09-04 13:28:10.220119+03', TRUE, 5, NULL, 'All Registrations', FALSE, TIMESTAMP WITH TIME ZONE '2025-09-04 13:17:56.997039+03', 0, '[]', NULL, 1, '66', 'table', TIMESTAMP WITH TIME ZONE '2025-09-05 09:44:35.386304+03', 2, 1, 5, TIMESTAMP WITH TIME ZONE '2025-09-04 13:17:56.920277+03', NULL),
(33, 'Locations', 'Locations {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE administrative_area_path AS (\n    -- roots\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aa.name::text AS administrative_area_path,\n        1 AS level\n    FROM app.administrative_areas aa\n    WHERE aa.parent_id IS NULL\n\n    UNION ALL\n\n    -- descendants\n    SELECT\n        aa.id,\n        aa.parent_id,\n        aa.name,\n        aap.administrative_area_path || '','' || aa.name,\n        aap.level + 1\n    FROM app.administrative_areas aa\n    JOIN administrative_area_path aap\n        ON aa.parent_id = aap.id\n),\n\npivot AS (\n    SELECT\n        id,\n\n        split_part(administrative_area_path, '','', 1)  AS level_1_name,\n        split_part(administrative_area_path, '','', 2)  AS level_2_name,\n        split_part(administrative_area_path, '','', 3)  AS level_3_name,\n        split_part(administrative_area_path, '','', 4)  AS level_4_name,\n        split_part(administrative_area_path, '','', 5)  AS level_5_name,\n        split_part(administrative_area_path, '','', 6)  AS level_6_name,\n        split_part(administrative_area_path, '','', 7)  AS level_7_name,\n        split_part(administrative_area_path, '','', 8)  AS level_8_name,\n        split_part(administrative_area_path, '','', 9)  AS level_9_name,\n        split_part(administrative_area_path, '','', 10) AS level_10_name\n\n    FROM administrative_area_path\n)\n\nSELECT\n\tl.id::text AS id,\n    l.name,\n    l.created_at,\n    l.updated_at,\n    l.deleted_at,\n    l.location_type,\n    l.valid_until,\n    l.administrative_area_id,\n    l.external_id,\n\n    aa.name AS administrative_area_name,\n\n    aap.administrative_area_path,\n    aap.level AS administrative_area_level,\n\n    -- include location itself in the final full path\n    CASE\n        WHEN aap.administrative_area_path IS NOT NULL\n            THEN aap.administrative_area_path || '','' || l.name\n        ELSE l.name\n    END AS full_path,\n\n    p.level_1_name,\n    p.level_2_name,\n    p.level_3_name,\n    p.level_4_name,\n    p.level_5_name,\n    p.level_6_name,\n    p.level_7_name,\n    p.level_8_name,\n    p.level_9_name,\n    p.level_10_name\n\nFROM app.locations l\n\nLEFT JOIN app.administrative_areas aa\n    ON aa.id = l.administrative_area_id\n\nLEFT JOIN administrative_area_path aap\n    ON aap.id = aa.id\n\nLEFT JOIN pivot p\n    ON p.id = aa.id;"}}', 'dataset', '{"name":"Locations","description":null,"collection_name":null}', '{"description":null,"archived":false,"display_type":"table","collection_position":10,"database_id":2,"collection_id":null,"official_collection":null,"name":"Locations","collection_name":null,"collection_authority_level":null,"creator_id":1,"updated_at":"2026-06-01T15:01:22.728774+02:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"WITH RECURSIVE administrative_area_path AS (\\n    -- roots\\n    SELECT\\n        aa.id,\\n        aa.parent_id,\\n        aa.name,\\n        aa.name::text AS administrative_area_path,\\n        1 AS level\\n    FROM app.administrative_areas aa\\n    WHERE aa.parent_id IS NULL\\n\\n    UNION ALL\\n\\n    -- descendants\\n    SELECT\\n        aa.id,\\n        aa.parent_id,\\n        aa.name,\\n        aap.administrative_area_path || '','' || aa.name,\\n        aap.level + 1\\n    FROM app.administrative_areas aa\\n    JOIN administrative_area_path aap\\n        ON aa.parent_id = aap.id\\n),\\n\\npivot AS (\\n    SELECT\\n        id,\\n\\n        split_part(administrative_area_path, '','', 1)  AS level_1_name,\\n        split_part(administrative_area_path, '','', 2)  AS level_2_name,\\n        split_part(administrative_area_path, '','', 3)  AS level_3_name,\\n        split_part(administrative_area_path, '','', 4)  AS level_4_name,\\n        split_part(administrative_area_path, '','', 5)  AS level_5_name,\\n        split_part(administrative_area_path, '','', 6)  AS level_6_name,\\n        split_part(administrative_area_path, '','', 7)  AS level_7_name,\\n        split_part(administrative_area_path, '','', 8)  AS level_8_name,\\n        split_part(administrative_area_path, '','', 9)  AS level_9_name,\\n        split_part(administrative_area_path, '','', 10) AS level_10_name\\n\\n    FROM administrative_area_path\\n)\\n\\nSELECT\\n\\tl.id::text AS id,\\n    l.name,\\n    l.created_at,\\n    l.updated_at,\\n    l.deleted_at,\\n    l.location_type,\\n    l.valid_until,\\n    l.administrative_area_id,\\n    l.external_id,\\n\\n    aa.name AS administrative_area_name,\\n\\n    aap.administrative_area_path,\\n    aap.level AS administrative_area_level,\\n\\n    -- include location itself in the final full path\\n    CASE\\n        WHEN aap.administrative_area_path IS NOT NULL\\n            THEN aap.administrative_area_path || '','' || l.name\\n        ELSE l.name\\n    END AS full_path,\\n\\n    p.level_1_name,\\n    p.level_2_name,\\n    p.level_3_name,\\n    p.level_4_name,\\n    p.level_5_name,\\n    p.level_6_name,\\n    p.level_7_name,\\n    p.level_8_name,\\n    p.level_9_name,\\n    p.level_10_name\\n\\nFROM app.locations l\\n\\nLEFT JOIN app.administrative_areas aa\\n    ON aa.id = l.administrative_area_id\\n\\nLEFT JOIN administrative_area_path aap\\n    ON aap.id = aa.id\\n\\nLEFT JOIN pivot p\\n    ON p.id = aa.id;\"}}","last_editor_id":1,"collection_location":null,"id":71,"last_edited_at":"2026-06-01T15:01:22.747728+02:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-09-04T13:31:14.91944+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-01 15:01:22.728774+02', TRUE, NULL, NULL, 'Locations', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-01 15:01:22.747728+02', 0, '[]', NULL, 1, '71', 'table', TIMESTAMP WITH TIME ZONE '2026-06-02 15:47:12.401605+02', 2, 1, 81, TIMESTAMP WITH TIME ZONE '2025-09-04 13:31:14.91944+03', NULL);             
