(47, 'No. of previous births', 'No. of previous births {"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT ''1'' AS previous_births, 0 AS results\nUNION ALL\nSELECT ''2'', 0\nUNION ALL\nSELECT ''3'', 0\nUNION ALL\nSELECT ''4'', 0\nUNION ALL\nSELECT ''5'', 0\nUNION ALL\nSELECT ''+5 years'', 0;"}}', 'dataset', '{"name":"No. of previous births","description":null,"collection_name":"Birth Models"}', '{"description":null,"archived":false,"display_type":"table","collection_position":2,"database_id":2,"collection_id":13,"official_collection":null,"name":"No. of previous births","collection_name":"Birth Models","collection_authority_level":null,"creator_id":1,"updated_at":"2025-09-11T13:18:34.203652+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"SELECT ''1'' AS previous_births, 0 AS results\\nUNION ALL\\nSELECT ''2'', 0\\nUNION ALL\\nSELECT ''3'', 0\\nUNION ALL\\nSELECT ''4'', 0\\nUNION ALL\\nSELECT ''5'', 0\\nUNION ALL\\nSELECT ''+5 years'', 0;\"}}","last_editor_id":1,"collection_location":"/7/","id":120,"last_edited_at":"2025-09-11T11:31:45.444053+03:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-09-11T11:04:45.943248+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', FALSE, TIMESTAMP WITH TIME ZONE '2025-09-11 13:18:34.203652+03', TRUE, 13, NULL, 'No. of previous births', FALSE, TIMESTAMP WITH TIME ZONE '2025-09-11 11:31:45.444053+03', 0, '[]', NULL, 1, '120', 'table', TIMESTAMP WITH TIME ZONE '2026-05-19 15:13:49.280942+01', 2, 1, 9, TIMESTAMP WITH TIME ZONE '2025-09-11 11:04:45.943248+03', NULL);   
