app\\\".\\\"users\\\".\\\"profile_image_path\\\" AS \\\"profile_image_path\\\",\\n  \\\"app\\\".\\\"users\\\".\\\"office_id\\\" AS \\\"office_id\\\",\\n  \\\"app\\\".\\\"users\\\".\\\"created_at\\\" AS \\\"created_at\\\",\\n  \\\"app\\\".\\\"users\\\".\\\"updated_at\\\" AS \\\"updated_at\\\",\\n  \\\"app\\\".\\\"users\\\".\\\"data\\\" AS \\\"data\\\",\\n  \\\"app\\\".\\\"users\\\".\\\"device\\\" AS \\\"device\\\"\\nFROM\\n  \\\"app\\\".\\\"users\\\"\"}}","last_editor_id":1,"collection_location":"/","id":170,"last_edited_at":"2026-05-26T16:39:03.418364+02:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2026-05-26T16:18:01.473651+02:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-01 15:26:15.0565+02', TRUE, 7, NULL, 'Users', FALSE, TIMESTAMP WITH TIME ZONE '2026-05-26 16:39:03.418364+02', 0, '[]', NULL, 1, '170', 'table', TIMESTAMP WITH TIME ZONE '2026-06-02 15:47:12.401605+02', 2, 1, 3, TIMESTAMP WITH TIME ZONE '2026-05-26 16:18:01.473651+02', NULL),
