(75, '% of Total Registrations Certified', '% of Total Registrations Certified {"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT\n  CASE WHEN has_certified THEN ''Certified'' ELSE ''Not Certified'' END AS group_name,\n  COUNT(*) AS count\nFROM (\n  SELECT\n    event_id,\n    BOOL_OR(action_type = ''PRINT_CERTIFICATE'') AS has_certified\n  FROM app.event_actions\n  WHERE action_type IN (''REGISTER'',''PRINT_CERTIFICATE'')\n  GROUP BY event_id\n  HAVING BOOL_OR(action_type = ''REGISTER'')\n) t\nGROUP BY has_certified;"}}', 'card', '{"name":"% of Total Registrations Certified","description":null,"collection_name":"OpenCRVS Core Dashboards"}', '{"description":null,"archived":true,"display_type":"pie","collection_position":null,"database_id":2,"collection_id":5,"official_collection":null,"name":"% of Total Registrations Certified","collection_name":"OpenCRVS Core Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2025-09-04T13:28:10.220119+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"SELECT\\n  CASE WHEN has_certified THEN ''Certified'' ELSE ''Not Certified'' END AS group_name,\\n  COUNT(*) AS count\\nFROM (\\n  SELECT\\n    event_id,\\n    BOOL_OR(action_type = ''PRINT_CERTIFICATE'') AS has_certified\\n  FROM app.event_actions\\n  WHERE action_type IN (''REGISTER'',''PRINT_CERTIFICATE'')\\n  GROUP BY event_id\\n  HAVING BOOL_OR(action_type = ''REGISTER'')\\n) t\\nGROUP BY has_certified;\"}}","last_editor_id":1,"collection_location":"/","id":57,"last_edited_at":"2025-08-19T16:32:34.576144+03:00","dashboardcard_count":1,"collection_type":null,"display":"pie","archived_directly":false,"verified":null,"dashboard_id":6,"created_at":"2025-08-19T16:32:34.556493+03:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TRUE, TIMESTAMP WITH TIME ZONE '2025-09-04 13:2