tails_causeOfDeathOther_symptom_four''->>''value'' = ''OTHER''\\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathOther_symptom_four_other'', '''')\\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathOther_symptom_four''->>''label'', '''')\\n        END,\\n        CASE\\n          WHEN base.declaration->''eventDetails_causeOfDeathOther_symptom_five''->>''value'' = ''OTHER''\\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathOther_symptom_five_other'', '''')\\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathOther_symptom_five''->>''label'', '''')\\n        END,\\n        CASE\\n          WHEN base.declaration->''eventDetails_causeOfDeathOther_symptom_six''->>''value'' = ''OTHER''\\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathOther_symptom_six_other'', '''')\\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathOther_symptom_six''->>''label'', '''')\\n        END,\\n        CASE\\n          WHEN base.declaration->''eventDetails_causeOfDeathOther_symptom_seven''->>''value'' = ''OTHER''\\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathOther_symptom_seven_other'', '''')\\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathOther_symptom_seven''->>''label'', '''')\\n        END,\\n        CASE\\n          WHEN base.declaration->''eventDetails_causeOfDeathOther_symptom_eight''->>''value'' = ''OTHER''\\n            THEN NULLIF(base.declaration->>''eventDetails_causeOfDeathOther_symptom_eight_other'', '''')\\n          ELSE NULLIF(base.declaration->''eventDetails_causeOfDeathOther_symptom_eight''->>''label'', '''')\\n        END\\n      ),\\n      ''''\\n    ) AS \\\"TextLine\\\",\\n    ''''::text AS \\\"CodeLine\\\",\\n    NULLIF(\\n      TRIM(\\n        COALESCE(base.declaration->''eventDetails_causeOfDeathOther_interval''->>''numericValue'', '''') || '' '' ||\\n        COALESCE(base.declaration->''eventDetails_causeOfDeathOther_interval''->>''unit'', '''')\\n      ),\\n      ''''\\n    ) AS \\\"IntervalLine\\\"\\n  FROM base\\n) t\\nWHERE NULLIF(TRIM(COALESCE(t.\\\"TextLine\\\", '''')), '''') IS NOT NULL\\nORDER BY \\\"CertificateKey\\\", \\\"LineNb\\\";\"}}","last_editor_id":1,"collection_location":"/","id":160,"last_edited_at":"2026-05-19T14:52:01.605379+01:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":true,"verified":null,"dashboard_id":14,"created_at":"2025-12-09T15:29:15.499054Z","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TRUE, TIMESTAMP WITH TIME ZONE '2026-05-19 16:13:47.946135+01', FALSE, 8, NULL, 'MEDCOD', FALSE, TIMESTAMP WITH TIME ZONE '2026-05-19 14:52:01.605379+01', 0, '[]', 14, 1, '160', 'table', TIMESTAMP WITH TIME ZONE '2026-05-19 16:13:24.029075+01', 2, 1, 143, TIMESTAMP WITH TIME ZONE '2025-12-09 15:29:15.499054+00', NULL); 
INSERT INTO "PUBLIC"."SEARCH_INDEX__TTVSSNKPF1NWNZ9SS4H6D" VALUES
(117, 'IDENT', 'IDENT {"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT DISTINCT ON (d.event_id)\n  d.\"CertificateKey\",\n  ''''::text AS \"LastChange\",\n  to_char(d.\"DateBirth\"::timestamp, ''DD/MM/YYYY'') AS \"DateBirth\",\n  to_char(d.\"DateDeath\"::timestamp, ''DD/MM/YYYY'') AS \"DateDeath\",\n  CASE\n    WHEN d.\"DateBirth\" IS NOT NULL AND d.\"DateDeath\" IS NOT NULL\n      THEN EXTRACT(YEAR FROM age(d.\"DateDeath\", d.\"DateBirth\"))::int || '' Years''\n    WHEN d.\"DeclaredAge\" IS NOT NULL\n      THEN d.\"DeclaredAge\"::text || '' Years''\n    ELSE NULL\n  END AS \"Age\",\n  d.\"Sex\",\n  d.\"Comments\"\nFROM (\n  SELECT\n    ea.event_id,\n    ea.created_at,\n    ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    NULLIF(ea.declaration->>''deceased_dob'','''')::date AS \"DateBirth\",\n    NULLIF(ea.declaration->>''deceased_eventDate'','''')::date AS \"DateDeath\",\n    NULLIF(ea.declaration->''deceased_age''->>''age'','''')::int AS \"DeclaredAge\",\n    CASE COALESCE(NULLIF(ea.declaration->>''deceased_gender'',''''),''9'')\n      WHEN ''1'' THEN ''Male''\n      WHEN ''2'' THEN ''Female''\n      WHEN ''8'' THEN ''Other''\n      ELSE ''Unknown''\n    END AS \"Sex\",\n    NULLIF(ea.annotation->>''review_comment'', '''') AS \"Comments\"\n  FROM analytics.event_actions ea\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND (\n      ea.declaration->>''irisOutput_ucCode'' IS NULL\n      OR ea.declaration->>''irisOutput_ucCode'' = ''None''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions r\n      WHERE r.event_id = ea.event_id\n        AND r.action_type = ''REGISTER''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions a\n      WHERE a.event_id = ea.event_id\n        AND a.action_type = ''ARCHIVE''\n    )\n) d\nORDER BY d.event_id, d.created_at DESC;"}}', 'card', '{"name":"IDENT","description":null,"collection_name":"Dashboards"}', '{"description":null,"archived":true,"display_type":"table","collection_position":null,"database_id":2,"collection_id":8,"official_collection":null,"name":"IDENT","collection_name":"Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2026-05-19T16:13:47.946135+01:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"SELECT DISTINCT ON (d.event_id)\\n  d.\\\"CertificateKey\\\",\\n  ''''::text AS \\\"LastChange\\\",\\n  to_char(d.\\\"DateBirth\\\"::timestamp, ''DD/MM/YYYY'') AS \\\"DateBirth\\\",\\n  to_char(d.\\\"DateDeath\\\"::timestamp, ''DD/MM/YYYY'') AS \\\"DateDeath\\\",\\n  CASE\\n    WHEN d.\\\"DateBirth\\\" IS NOT NULL AND d.\\\"DateDeath\\\" IS NOT NULL\\n      THEN EXTRACT(YEAR FROM age(d.\\\"DateDeath\\\", d.\\\"DateBirth\\\"))::int || '' Years''\\n    WHEN d.\\\"DeclaredAge\\\" IS NOT NULL\\n      THEN d.\\\"DeclaredAge\\\"::text || '' Years''\\n    ELSE NULL\\n  END AS \\\"Age\\\",\\n  d.\\\"Sex\\\",\\n  d.\\\"Comments\\\"\\nFROM (\\n  SELECT\\n    ea.event_id,\\n    ea.created_at,\\n    ea.declaration->>''deceased_certificateKey'' AS \\\"CertificateKey\\\",\\n    NULLIF(ea.declaration->>''deceased_dob'','''')::date AS \\\"DateBirth\\\",\\n    NULLIF(ea.declaration->>''deceased_eventDate'','''')::date AS \\\"DateDeath\\\",\\n    NULLIF(ea.declaration->''deceased_age''->>''age'','''')::int AS \\\"DeclaredAge\\\",\\n    CASE COALESCE(NULLIF(ea.declaration->>''deceased_gender'',''''),''9'')\\n      WHEN ''1'' THEN ''Male''\\n      WHEN ''2'' THEN ''Female''\\n      WHEN ''8'' THEN ''Other''\\n      ELSE ''Unknown''\\n    END AS \\\"Sex\\\",\\n    NULLIF(ea.annotation->>''review_comment'', '''') AS \\\"Comments\\\"\\n  FROM analytics.event_actions ea\\n  WHERE ea.action_type = ''DECLARE''\\n    AND ea.registration_number IS NULL\\n    AND (\\n      ea.declaration->>''irisOutput_ucCode'' IS NULL\\n      OR ea.declaration->>''irisOutput_ucCode'' = ''None''\\n    )\\n    AND NOT EXISTS (\\n      SELECT 1\\n      FROM analytics.event_actions r\\n      WHERE r.event_id = ea.event_id\\n        AND r.action_type = ''REGISTER''\\n    )\\n    AND NOT EXISTS (\\n      SELECT 1\\n      FROM analytics.event_actions a\\n      WHERE a.event_id = ea.event_id\\n        AND a.action_type = ''ARCHIVE''\\n    )\\n) d\\nORDER BY d.event_id, d.created_at DESC;\"}}","last_editor_id":1,"collection_location":"/","id":161,"last_edited_at":"2026-05-19T14:51:41.326179+01:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":true,"verified":null,"dashboard_id":14,"created_at":"2025-12-10T14:12:15.994085Z","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TIMESTAMP WITH TIME ZONE '2026-06-02 15:59:33.822494+02', TRUE, TIMESTAMP WITH TIME ZONE '2026-05-19 16:13:47.946135+01', FALSE, 8, NULL, 'IDENT', FALSE, TIMESTAMP WITH TIME ZONE '2026-05-19 14:51:41.326179+01', 0, '[]', 14, 1, '161', 'table', TIMESTAMP WITH TIME ZONE '2026-05-19 16:13:24.029075+01', 2, 1, 150, TIMESTAMP WITH TIME ZONE '2025-12-10 14:12:15.994085+00', NULL);         
