(170, U&'Major causes \2014 Female', U&'Major causes \2014 Female {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH causes AS (\\n  SELECT\\n    (\\n      declaration #>> ARRAY[''irisOutput_ucCode'']\\n    ) AS uc_code,\\n    (\\n      declaration #>> ARRAY[\\n        ''eventDetails_causeOfDeathA_symptom_one'',\\n        ''label''\\n      ]\\n    ) AS symptom,\\n    COUNT(*) AS count,\\n    ROUND(\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\n      2\\n    ) AS percentage\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n  GROUP BY 1, 2\\n),\\n\\ntop10 AS (\\n  SELECT *\\n  FROM causes\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\n  LIMIT 10\\n),\\n\\nranked AS (\\n  SELECT\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\n    uc_code,\\n    symptom,\\n    count,\\n    percentage\\n  FROM top10\\n)\\n\\nSELECT\\n  rank AS \\"RANK\\",\\n  uc_code AS \\"declaration \2192 irisOutput_ucCode\\",\\n  symptom AS \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\",\\n  count,\\n  percentage\\nFROM ranked\\n\\nUNION ALL\\n\\nSELECT\\n  ''Total (Top 10)'',\\n  '''',\\n  '''',\\n  SUM(count),\\n  ROUND(SUM(percentage), 2)\\nFROM ranked;"}}', 'card', U&'{"name":"Major causes \2014 Female","description":null,"collection_name":"Dashboards"}', U&'{"description":null,"archived":false,"display_type":"table","collection_position":null,"database_id":2,"collection_id":8,"official_collection":null,"name":"Major causes \2014 Female","collection_name":"Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2026-06-03T10:12:03.204401+02:00","moderated_status":null,"dataset_query":"{\\"database\\":2,\\"type\\":\\"native\\",\\"native\\":{\\"template-tags\\":{},\\"query\\":\\"WITH causes AS (\\\\n  SELECT\\\\n    (\\\\n      declaration #>> ARRAY[''irisOutput_ucCode'']\\\\n    ) AS uc_code,\\\\n    (\\\\n      declaration #>> ARRAY[\\\\n        ''eventDetails_causeOfDeathA_symptom_one'',\\\\n        ''label''\\\\n      ]\\\\n    ) AS symptom,\\\\n    COUNT(*) AS count,\\\\n    ROUND(\\\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\\\n      2\\\\n    ) AS percentage\\\\n  FROM analytics.event_actions\\\\n  WHERE action_type = ''REGISTER''\\\\n  GROUP BY 1, 2\\\\n),\\\\n\\\\ntop10 AS (\\\\n  SELECT *\\\\n  FROM causes\\\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\\\n  LIMIT 10\\\\n),\\\\n\\\\nranked AS (\\\\n  SELECT\\\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\\\n    uc_code,\\\\n    symptom,\\\\n    count,\\\\n    percentage\\\\n  FROM top10\\\\n)\\\\n\\\\nSELECT\\\\n  rank AS \\\\\\"RANK\\\\\\",\\\\n  uc_code AS \\\\\\"declaration \2192 irisOutput_ucCode\\\\\\",\\\\n  symptom AS \\\\\\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\\\\\",\\\\n  count,\\\\n  percentage\\\\nFROM ranked\\\\n\\\\nUNION ALL\\\\n\\\\nSELECT\\\\n  ''Total (Top 10)'',\\\\n  '''',\\\\n  '''',\\\\n  SUM(count),\\\\n  ROUND(SUM(percentage), 2)\\\\nFROM ranked;\\"}}","last_editor_id":1,"collection_location":"/","id":177,"last_edited_at":"2026-06-03T10:12:03.217624+02:00","dashboardcard_count":2,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":13,"created_at":"2026-06-01T16:15:37.313892+02:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-06-03 10:12:09.112767+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:12:09.112767+02', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-03 10:12:03.204401+02', FALSE, 8, NULL, U&'Major causes \2014 Female', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-03 10:12:03.217624+02', 2, '[]', 13, 1, '177', 'table', TIMESTAMP WITH TIME ZONE '2026-06-03 10:11:27.237079+02', 2, 1, 66, TIMESTAMP WITH TIME ZONE '2026-06-01 16:15:37.313892+02', NULL),
