(41, 'Printed + Registered Distinct printed and registered records', 'Printed + Registered Distinct printed and registered records {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH printed AS (\n  SELECT *\n  FROM analytics.event_actions\n  WHERE action_type = ''PRINT_CERTIFICATE''\n),\nregistered AS (\n  SELECT *\n  FROM analytics.event_actions\n  WHERE action_type = ''REGISTER''\n)\n-- all printed, plus registered that are not printed\nSELECT p.*\nFROM printed p\nUNION ALL\nSELECT r.*\nFROM registered r\nLEFT JOIN printed p USING (event_id)\nWHERE p.event_id IS NULL;"}}', 'dataset', '{"name":"Printed + Registered","description":"Distinct printed and registered records","collection_name":"Models"}', '{"description":"Distinct printed and registered records","archived":false,"display_type":"table","collection_position":null,"database_id":2,"collection_id":7,"official_collection":null,"name":"Printed + Registered","collection_name":"Models","collection_authority_level":null,"creator_id":1,"updated_at":"2025-10-10T11:08:45.675529+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"WITH printed AS (\\n  SELECT *\\n  FROM analytics.event_actions\\n  WHERE action_type = ''PRINT_CERTIFICATE''\\n),\\nregistered AS (\\n  SELECT *\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n)\\n-- all printed, plus registered that are not printed\\nSELECT p.*\\nFROM printed p\\nUNION ALL\\nSELECT r.*\\nFROM registered r\\nLEFT JOIN printed p USING (event_id)\\nWHERE p.event_id IS NULL;\"}}","last_editor_id":1,"collection_location":"/","id":104,"last_edited_at":"2025-10-10T11:08:45.692924+03:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-09-09T17:02:56.305468+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', FALSE, TIMESTAMP WITH TIME ZONE '2025-10-10 11:08:45.675529+03', FALSE, 7, NULL, 'Printed + Registered', FALSE, TIMESTAMP WITH TIME ZONE '2025-10-10 11:08:45.692924+03', 0, '[]', NULL, 1, '104', 'table', TIMESTAMP WITH TIME ZONE '2025-12-09 15:27:47.975772+00', 2, 1, 27, TIMESTAMP WITH TIME ZONE '2025-09-09 17:02:56.305468+03', NULL);            
