(48, 'Educational Levels', 'Educational Levels {"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT ''No schooling'' AS edicational_level, 0 AS results\nUNION ALL\nSELECT ''Primary'', 0\nUNION ALL\nSELECT ''Secondary'', 0\nUNION ALL\nSELECT ''Tertiary'', 0"}}', 'dataset', '{"name":"Educational Levels","description":null,"collection_name":"Birth Models"}', '{"description":null,"archived":false,"display_type":"table","collection_position":1,"database_id":2,"collection_id":13,"official_collection":null,"name":"Educational Levels","collection_name":"Birth Models","collection_authority_level":null,"creator_id":1,"updated_at":"2025-09-11T13:18:34.203652+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"SELECT ''No schooling'' AS edicational_level, 0 AS results\\nUNION ALL\\nSELECT ''Primary'', 0\\nUNION ALL\\nSELECT ''Secondary'', 0\\nUNION ALL\\nSELECT ''Tertiary'', 0\"}}","last_editor_id":1,"collection_location":"/7/","id":122,"last_edited_at":"2025-09-11T13:18:34.215919+03:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-09-11T13:18:34.203652+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', FALSE, TIMESTAMP WITH TIME ZONE '2025-09-11 13:18:34.203652+03', TRUE, 13, NULL, 'Educational Levels', FALSE, TIMESTAMP WITH TIME ZONE '2025-09-11 13:18:34.215919+03', 0, '[]', NULL, 1, '122', 'table', TIMESTAMP WITH TIME ZONE '2026-05-19 14:58:47.547889+01', 2, 1, 6, TIMESTAMP WITH TIME ZONE '2025-09-11 13:18:34.203652+03', NULL),
(49, 'Births completeness rates Completeness rates per location per year, based on country provided population and crude birth rate statistics', 'Births completeness rates Completeness rates per location per year, based on country provided population and crude birth rate statistics {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH RECURSIVE levels AS (\n    -- root = 1, children increment\n    SELECT id, parent_id, 1 AS level\n    FROM analytics.locations\n    WHERE parent_id IS NULL\n    UNION ALL\n    SELECT l.id, l.parent_id, lv.level + 1\n    FROM analytics.locations l\n    JOIN levels lv ON l.parent_id = lv.id\n),\n-- ancestor/descendant closure: every node is ancestor of itself and all its descendants\nclosure AS (\n    SELECT id AS ancestor_id, id AS descendant_id\n    FROM analytics.locations\n    UNION ALL\n    SELECT c.ancestor_id, l.id AS descendant_id\n    FROM closure c\n    JOIN analytics.locations l ON l.parent_id = c.descendant_id\n),\n-- counts at leaf/origin locations by year\ncounts AS (\n\tSELECT ea.created_at_location AS location_id,\n\t       EXTRACT(YEAR FROM ea.created_at)::int AS year,\n\t       COUNT(*) AS cnt\n\tFROM analytics.event_actions ea\n\tWHERE ea.action_type = ''REGISTER''\n\t  AND ea.event_type  = ''birth''\n\t  AND ea.created_at IS NOT NULL\n\t  AND ea.created_at_location IS NOT NULL\n\t  AND (ea.declaration->>''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\n\tGROUP BY ea.created_at_location, year\n),\n-- roll up descendant counts to each ancestor (this is the named query)\nbirth_registrations_per_location AS (\n    SELECT c.ancestor_id AS location_id,\n           cnt.year,\n           SUM(cnt.cnt) AS register_count\n    FROM closure c\n    JOIN counts cnt ON cnt.location_id = c.descendant_id\n    GROUP BY c.ancestor_id, cnt.year\n)\nSELECT \n    l.id,\n    l.name,\n    s.year,\n    s.crude_birth_rate,\n    s.total_population,\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\n    COALESCE(br.register_count, 0) AS register_count,\n\t(register_count / (s.total_population / 1000 * s.crude_birth_rate) * 100) as completeness_rate,\n    lv.level,\n    ll.name AS level_name\nFROM analytics.locations l\nJOIN analytics.location_statistics s\n  ON s.name = l.name\nLEFT JOIN birth_registrations_per_location br\n  ON br.location_id = l.id AND br.year = s.year\nLEFT JOIN levels lv\n  ON lv.id = l.id\nLEFT JOIN analytics.location_levels ll\n  ON ll.level = lv.level\nORDER BY s.year DESC, register_count DESC;"}}', 'dataset', '{"name":"Births completeness rates","description":"Completeness rates per location per year, based on country provided population and crude birth rate statistics","collection_name":"Births"}', '{"description":"Completeness rates per location per year, based on country provided population and crude birth rate statistics","archived":false,"display_type":"table","collection_position":1,"database_id":2,"collection_id":9,"official_collection":null,"name":"Births completeness rates","collection_name":"Births","collection_authority_level":null,"creator_id":1,"updated_at":"2025-10-10T13:59:59.326827+03:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"WITH RECURSIVE levels AS (\\n    -- root = 1, children increment\\n    SELECT id, parent_id, 1 AS level\\n    FROM analytics.locations\\n    WHERE parent_id IS NULL\\n    UNION ALL\\n    SELECT l.id, l.parent_id, lv.level + 1\\n    FROM analytics.locations l\\n    JOIN levels lv ON l.parent_id = lv.id\\n),\\n-- ancestor/descendant closure: every node is ancestor of itself and all its descendants\\nclosure AS (\\n    SELECT id AS ancestor_id, id AS descendant_id\\n    FROM analytics.locations\\n    UNION ALL\\n    SELECT c.ancestor_id, l.id AS descendant_id\\n    FROM closure c\\n    JOIN analytics.locations l ON l.parent_id = c.descendant_id\\n),\\n-- counts at leaf/origin locations by year\\ncounts AS (\\n\\tSELECT ea.created_at_location AS location_id,\\n\\t       EXTRACT(YEAR FROM ea.created_at)::int AS year,\\n\\t       COUNT(*) AS cnt\\n\\tFROM analytics.event_actions ea\\n\\tWHERE ea.action_type = ''REGISTER''\\n\\t  AND ea.event_type  = ''birth''\\n\\t  AND ea.created_at IS NOT NULL\\n\\t  AND ea.created_at_location IS NOT NULL\\n\\t  AND (ea.declaration->>''child_dob'')::date > ea.created_at::date - INTERVAL ''365 days''\\n\\tGROUP BY ea.created_at_location, year\\n),\\n-- roll up descendant counts to each ancestor (this is the named query)\\nbirth_registrations_per_location AS (\\n    SELECT c.ancestor_id AS location_id,\\n           cnt.year,\\n           SUM(cnt.cnt) AS register_count\\n    FROM closure c\\n    JOIN counts cnt ON cnt.location_id = c.descendant_id\\n    GROUP BY c.ancestor_id, cnt.year\\n)\\nSELECT \\n    l.id,\\n    l.name,\\n    s.year,\\n    s.crude_birth_rate,\\n    s.total_population,\\n    (s.total_population / 1000 * s.crude_birth_rate) AS estimated_births,\\n    COALESCE(br.register_count, 0) AS register_count,\\n\\t(register_count / (s.total_population / 1000 * s.crude_birth_rate) * 100) as completeness_rate,\\n    lv.level,\\n    ll.name AS level_name\\nFROM analytics.locations l\\nJOIN analytics.location_statistics s\\n  ON s.name = l.name\\nLEFT JOIN birth_registrations_per_location br\\n  ON br.location_id = l.id AND br.year = s.year\\nLEFT JOIN levels lv\\n  ON lv.id = l.id\\nLEFT JOIN analytics.location_levels ll\\n  ON ll.level = lv.level\\nORDER BY s.year DESC, register_count DESC;\"}}","last_editor_id":1,"collection_location":"/6/","id":124,"last_edited_at":"2025-10-10T13:59:59.337447+03:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2025-09-12T10:07:18.436943+03:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', FALSE, TIMESTAMP WITH