INSERT INTO "PUBLIC"."SEARCH_INDEX__SX4_OB0QXPFEOXJCAPXT4" VALUES
(52, 'IDENT Model', 'IDENT Model {"database":2,"type":"native","native":{"template-tags":{},"query":"SELECT DISTINCT ON (d.event_id)\n  d.location_id,\n  d.created_at,\n  d.location_name,\n  d.\"CertificateKey\",\n  ''''::text AS \"LastChange\",\n  to_char(d.\"DateBirth\"::timestamp, ''DD/MM/YYYY'') AS \"DateBirth\",\n  to_char(d.\"DateDeath\"::timestamp, ''DD/MM/YYYY'') AS \"DateDeath\",\n  CASE\n    WHEN d.\"DateBirth\" IS NOT NULL AND d.\"DateDeath\" IS NOT NULL\n      THEN EXTRACT(YEAR FROM age(d.\"DateDeath\", d.\"DateBirth\"))::int || '' Years''\n    WHEN d.\"DeclaredAge\" IS NOT NULL\n      THEN d.\"DeclaredAge\"::text || '' Years''\n    ELSE NULL\n  END AS \"Age\",\n  d.\"Sex\",\n  d.\"Comments\"\nFROM (\n  SELECT\n    ea.event_id,\n    ea.created_at,\n    ea.created_at_location AS location_id,\n    l.name AS location_name,\n    ea.declaration->>''deceased_certificateKey'' AS \"CertificateKey\",\n    NULLIF(ea.declaration->>''deceased_dob'','''')::date AS \"DateBirth\",\n    NULLIF(ea.declaration->>''deceased_eventDate'','''')::date AS \"DateDeath\",\n    NULLIF(ea.declaration->''deceased_age''->>''age'','''')::int AS \"DeclaredAge\",\n    CASE COALESCE(NULLIF(ea.declaration->>''deceased_gender'',''''),''9'')\n      WHEN ''1'' THEN ''Male''\n      WHEN ''2'' THEN ''Female''\n      WHEN ''8'' THEN ''Other''\n      ELSE ''Unknown''\n    END AS \"Sex\",\n    NULLIF(ea.annotation->>''review_comment'', '''') AS \"Comments\"\n  FROM analytics.event_actions ea\n  LEFT JOIN analytics.locations l\n    ON ea.created_at_location = l.id\n  WHERE ea.action_type = ''DECLARE''\n    AND ea.registration_number IS NULL\n    AND (\n      ea.declaration->>''irisOutput_ucCode'' IS NULL\n      OR ea.declaration->>''irisOutput_ucCode'' = ''None''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions r\n      WHERE r.event_id = ea.event_id\n        AND r.action_type = ''REGISTER''\n    )\n    AND NOT EXISTS (\n      SELECT 1\n      FROM analytics.event_actions a\n      WHERE a.event_id = ea.event_id\n        AND a.action_type = ''ARCHIVE''\n    )\n) d\nORDER BY d.event_id, d.created_at DESC;"}}', 'dataset', '{"name":"IDENT Model","description":null,"collection_name":"Models"}', '{"description":null,"archived":false,"display_type":"table","collection_position":3,"database_id":2,"collection_id":7,"official_collection":null,"name":"IDENT Model","collection_name":"Models","collection_authority_level":null,"creator_id":1,"updated_at":"2026-06-01T15:26:15.0565+02:00","moderated_status":null,"dataset_query":"{\"database\":2,\"type\":\"native\",\"native\":{\"template-tags\":{},\"query\":\"SELECT DISTINCT ON (d.event_id)\\n  d.location_id,\\n  d.created_at,\\n  d.location_name,\\n  d.\\\"CertificateKey\\\",\\n  ''''::text AS \\\"LastChange\\\",\\n  to_char(d.\\\"DateBirth\\\"::timestamp, ''DD/MM/YYYY'') AS \\\"DateBirth\\\",\\n  to_char(d.\\\"DateDeath\\\"::timestamp, ''DD/MM/YYYY'') AS \\\"DateDeath\\\",\\n  CASE\\n    WHEN d.\\\"DateBirth\\\" IS NOT NULL AND d.\\\"DateDeath\\\" IS NOT NULL\\n      THEN EXTRACT(YEAR FROM age(d.\\\"DateDeath\\\", d.\\\"DateBirth\\\"))::int || '' Years''\\n    WHEN d.\\\"DeclaredAge\\\" IS NOT NULL\\n      THEN d.\\\"DeclaredAge\\\"::text || '' Years''\\n    ELSE NULL\\n  END AS \\\"Age\\\",\\n  d.\\\"Sex\\\",\\n  d.\\\"Comments\\\"\\nFROM (\\n  SELECT\\n    ea.event_id,\\n    ea.created_at,\\n    ea.created_at_location AS location_id,\\n    l.name AS location_name,\\n    ea.declaration->>''deceased_certificateKey'' AS \\\"CertificateKey\\\",\\n    NULLIF(ea.declaration->>''deceased_dob'','''')::date AS \\\"DateBirth\\\",\\n    NULLIF(ea.declaration->>''deceased_eventDate'','''')::date AS \\\"DateDeath\\\",\\n    NULLIF(ea.declaration->''deceased_age''->>''age'','''')::int AS \\\"DeclaredAge\\\",\\n    CASE COALESCE(NULLIF(ea.declaration->>''deceased_gender'',''''),''9'')\\n      WHEN ''1'' THEN ''Male''\\n      WHEN ''2'' THEN ''Female''\\n      WHEN ''8'' THEN ''Other''\\n      ELSE ''Unknown''\\n    END AS \\\"Sex\\\",\\n    NULLIF(ea.annotation->>''review_comment'', '''') AS \\\"Comments\\\"\\n  FROM analytics.event_actions ea\\n  LEFT JOIN analytics.locations l\\n    ON ea.created_at_location = l.id\\n  WHERE ea.action_type = ''DECLARE''\\n    AND ea.registration_number IS NULL\\n    AND (\\n      ea.declaration->>''irisOutput_ucCode'' IS NULL\\n      OR ea.declaration->>''irisOutput_ucCode'' = ''None''\\n    )\\n    AND NOT EXISTS (\\n      SELECT 1\\n      FROM analytics.event_actions r\\n      WHERE r.event_id = ea.event_id\\n        AND r.action_type = ''REGISTER''\\n    )\\n    AND NOT EXISTS (\\n      SELECT 1\\n      FROM analytics.event_actions a\\n      WHERE a.event_id = ea.event_id\\n        AND a.action_type = ''ARCHIVE''\\n    )\\n) d\\nORDER BY d.event_id, d.created_at DESC;\"}}","last_editor_id":1,"collection_location":"/","id":164,"last_edited_at":"2026-05-20T16:03:04.595367+01:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":null,"created_at":"2026-05-19T14:57:57.406491+01:00","model":"dataset"}', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-01 15:26:15.0565+02', TRUE, 7, NULL, 'IDENT Model', FALSE, TIMESTAMP WITH TIME ZONE '2026-05-20 16:03:04.595367+01', 0, '[]', NULL, 1, '164', 'table', TIMESTAMP WITH TIME ZONE '2026-05-26 14:09:40.81772+02', 2, 1, 19, TIMESTAMP WITH TIME ZONE '2026-05-19 14:57:57.406491+01', NULL); 
