\"}],\\" \\",[\\"field\\",929,{\\"base-type\\":\\"type/Text\\"}]],\\"Gender\\":[\\"case\\",[[[\\"=\\",[\\"field\\",747,{\\"base-type\\":\\"type/Text\\"}],\\"1\\"],\\"MALE\\"],[[\\"=\\",[\\"field\\",747,{\\"base-type\\":\\"type/Text\\"}],\\"2\\"],\\"FEMALE\\"],[[\\"=\\",[\\"field\\",747,{\\"base-type\\":\\"type/Text\\"}],\\"8\\"],\\"OTHER\\"]],{\\"default\\":\\"UNKNOWN\\"}]},\\"breakout\\":[[\\"expression\\",\\"Gender\\",{\\"base-type\\":\\"type/Text\\"}],[\\"field\\",757,{\\"base-type\\":\\"type/Text\\"}]],\\"order-by\\":[[\\"desc\\",[\\"aggregation\\",0,{\\"base-type\\":\\"type/Integer\\"}]]],\\"aggregation\\":[[\\"count\\"]]}}","last_editor_id":1,"collection_location":"/","id":176,"last_edited_at":"2026-06-01T16:23:43.758326+02:00","dashboardcard_count":1,"collection_type":null,"display":"bar","archived_directly":false,"verified":null,"dashboard_id":13,"created_at":"2026-06-01T15:48:25.652443+02:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-01 16:23:43.751609+02', FALSE, 8, NULL, 'Top 10 causes of death - Male vs Female', TRUE, TIMESTAMP WITH TIME ZONE '2026-06-01 16:23:43.758326+02', 1, '[258,278,345,749,756,757,758,872,907,931,1016]', 13, 1, '176', 'bar', TIMESTAMP WITH TIME ZONE '2026-06-03 10:29:56.063754+02', 2, 1, 78, TIMESTAMP WITH TIME ZONE '2026-06-01 15:48:25.652443+02', NULL),
(130, U&'Major causes \2014 Female', U&'Major causes \2014 Female {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH causes AS (\\n  SELECT\\n    (\\n      declaration #>> ARRAY[''irisOutput_ucCode'']\\n    ) AS uc_code,\\n    (\\n      declaration #>> ARRAY[\\n        ''eventDetails_causeOfDeathA_symptom_one'',\\n        ''label''\\n      ]\\n    ) AS symptom,\\n    COUNT(*) AS count,\\n    ROUND(\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\n      2\\n    ) AS percentage\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n  GROUP BY 1, 2\\n),\\n\\ntop10 AS (\\n  SELECT *\\n  FROM causes\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\n  LIMIT 10\\n),\\n\\nranked AS (\\n  SELECT\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\n    uc_code,\\n    symptom,\\n    count,\\n    percentage\\n  FROM top10\\n)\\n\\nSELECT\\n  rank AS \\"RANK\\",\\n  uc_code AS \\"declaration \2192 irisOutput_ucCode\\",\\n  symptom AS \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\",\\n  count,\\n  percentage\\nFROM ranked\\n\\nUNION ALL\\n\\nSELECT\\n  ''Total (Top 10)'',\\n  '''',\\n  '''',\\n  SUM(count),\\n  ROUND(SUM(percentage), 2)\\nFROM ranked;"}}', 'card', U&'{"name":"Major causes \2014 Female","description":null,"collection_name":"Dashboards"}', U&'{"description":null,"archived":false,"display_type":"table","collection_position":null,"database_id":2,"collection_id":8,"official_collection":null,"name":"Major causes \2014 Female","collection_name":"Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2026-06-03T10:12:03.204401+02:00","moderated_status":null,"dataset_query":"{\\"database\\":2,\\"type\\":\\"native\\",\\"native\\":{\\"template-tags\\":{},\\"query\\":\\"WITH causes AS (\\\\n  SELECT\\\\n    (\\\\n      declaration #>> ARRAY[''irisOutput_ucCode'']\\\\n    ) AS uc_code,\\\\n    (\\\\n      declaration #>> ARRAY[\\\\n        ''eventDetails_causeOfDeathA_symptom_one'',\\\\n        ''label''\\\\n      ]\\\\n    ) AS symptom,\\\\n    COUNT(*) AS count,\\\\n    ROUND(\\\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\\\n      2\\\\n    ) AS percentage\\\\n  FROM analytics.event_actions\\\\n  WHERE action_type = ''REGISTER''\\\\n  GROUP BY 1, 2\\\\n),\\\\n\\\\ntop10 AS (\\\\n  SELECT *\\\\n  FROM causes\\\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\\\n  LIMIT 10\\\\n),\\\\n\\\\nranked AS (\\\\n  SELECT\\\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\\\n    uc_code,\\\\n    symptom,\\\\n    count,\\\\n    percentage\\\\n  FROM top10\\\\n)\\\\n\\\\nSELECT\\\\n  rank AS \\\\\\"RANK\\\\\\",\\\\n  uc_code AS \\\\\\"declaration \2192 irisOutput_ucCode\\\\\\",\\\\n  symptom AS \\\\\\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\\\\\",\\\\n  count,\\\\n  percentage\\\\nFROM ranked\\\\n\\\\nUNION ALL\\\\n\\\\nSELECT\\\\n  ''Total (Top 10)'',\\\\n  '''',\\\\n  '''',\\\\n  SUM(count),\\\\n  ROUND(SUM(percentage), 2)\\\\nFROM ranked;\\"}}","last_editor_id":1,"collection_location":"/","id":177,"last_edited_at":"2026-06-03T10:12:03.217624+02:00","dashboardcard_count":1,"collection_type":null,"display":"table","archived_directly":false,"verified":null,"dashboard_id":13,"created_at":"2026-06-01T16:15:37.313892+02:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-03 10:12:03.204401+02', FALSE, 8, NULL, U&'Major causes \2014 Female', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-03 10:12:03.217624+02', 1, '[]', 13, 1, '177', 'table', TIMESTAMP WITH TIME ZONE '2026-06-03 10:29:56.084604+02', 2, 1, 75, TIMESTAMP WITH TIME ZONE '2026-06-01 16:15:37.313892+02', NULL); 
