(137, 'Top 10 causes of death -- test', U&'Top 10 causes of death -- test {"database":2,"type":"native","native":{"template-tags":{},"query":"WITH causes AS (\\n  SELECT\\n    declaration #>> ARRAY[''irisOutput_ucCode''] AS uc_code,\\n    declaration #>> ARRAY[\\n      ''eventDetails_causeOfDeathA_symptom_one'',\\n      ''label''\\n    ] AS symptom,\\n    COUNT(*) AS count,\\n    ROUND(\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\n      2\\n    ) AS percentage\\n  FROM analytics.event_actions\\n  WHERE action_type = ''REGISTER''\\n  GROUP BY 1, 2\\n),\\n\\ntop10 AS (\\n  SELECT *\\n  FROM causes\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\n  LIMIT 10\\n),\\n\\nranked AS (\\n  SELECT\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\n    uc_code,\\n    symptom,\\n    count,\\n    percentage\\n  FROM top10\\n)\\n\\nSELECT\\n  rank AS \\"RANK\\",\\n  uc_code AS \\"declaration \2192 irisOutput_ucCode\\",\\n  symptom AS \\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\",\\n  count,\\n  percentage\\nFROM ranked;"}}', 'card', '{"name":"Top 10 causes of death -- test","description":null,"collection_name":"Dashboards"}', U&'{"description":null,"archived":true,"display_type":"table","collection_position":null,"database_id":2,"collection_id":8,"official_collection":null,"name":"Top 10 causes of death -- test","collection_name":"Dashboards","collection_authority_level":null,"creator_id":1,"updated_at":"2026-06-02T16:44:10.479626+02:00","moderated_status":null,"dataset_query":"{\\"database\\":2,\\"type\\":\\"native\\",\\"native\\":{\\"template-tags\\":{},\\"query\\":\\"WITH causes AS (\\\\n  SELECT\\\\n    declaration #>> ARRAY[''irisOutput_ucCode''] AS uc_code,\\\\n    declaration #>> ARRAY[\\\\n      ''eventDetails_causeOfDeathA_symptom_one'',\\\\n      ''label''\\\\n    ] AS symptom,\\\\n    COUNT(*) AS count,\\\\n    ROUND(\\\\n      100.0 * COUNT(*) / SUM(COUNT(*)) OVER (),\\\\n      2\\\\n    ) AS percentage\\\\n  FROM analytics.event_actions\\\\n  WHERE action_type = ''REGISTER''\\\\n  GROUP BY 1, 2\\\\n),\\\\n\\\\ntop10 AS (\\\\n  SELECT *\\\\n  FROM causes\\\\n  ORDER BY count DESC, uc_code ASC, symptom ASC\\\\n  LIMIT 10\\\\n),\\\\n\\\\nranked AS (\\\\n  SELECT\\\\n    ''#'' || ROW_NUMBER() OVER (ORDER BY count DESC, uc_code ASC, symptom ASC) AS rank,\\\\n    uc_code,\\\\n    symptom,\\\\n    count,\\\\n    percentage\\\\n  FROM top10\\\\n)\\\\n\\\\nSELECT\\\\n  rank AS \\\\\\"RANK\\\\\\",\\\\n  uc_code AS \\\\\\"declaration \2192 irisOutput_ucCode\\\\\\",\\\\n  symptom AS \\\\\\"declaration \2192 eventDetails_causeOfDeathA_symptom__eb6b17b1\\\\\\",\\\\n  count,\\\\n  percentage\\\\nFROM ranked;\\"}}","last_editor_id":1,"collection_location":"/","id":184,"last_edited_at":"2026-06-02T16:40:27.323165+02:00","dashboardcard_count":0,"collection_type":null,"display":"table","archived_directly":true,"verified":null,"dashboard_id":13,"created_at":"2026-06-02T16:40:27.284468+02:00","model":"card"}', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', TIMESTAMP WITH TIME ZONE '2026-06-03 10:59:52.037997+02', TRUE, TIMESTAMP WITH TIME ZONE '2026-06-02 16:44:10.479626+02', FALSE, 8, NULL, 'Top 10 causes of death -- test', FALSE, TIMESTAMP WITH TIME ZONE '2026-06-02 16:40:27.323165+02', 0, '[]', 13, 1, '184', 'table', TIMESTAMP WITH TIME ZONE '2026-06-02 16:44:00.102079+02', 2, 1, 3, TIMESTAMP WITH TIME ZONE '2026-06-02 16:40:27.284468+02', NULL);           
